def _parse_date(ts: str) -> str:
    """Convert Unix timestamp string to YYYY-MM-DD."""
    return date.fromtimestamp(int(ts)).isoformat()

def fetch_fear_greed(start_date: str, end_date: str) -> dict[str, tuple[int, str]]:
    """
    Fetch Fear & Greed index for date range.

    Returns: {date_str: (value_int, label_str)}
    Example: {"2026-04-24": (39, "Fear")}
    """
    days_needed = (date.fromisoformat(end_date) - date.fromisoformat(start_date)).days + 3
    try:
        resp = requests.get(BASE_URL, params={"limit": days_needed}, timeout=TIMEOUT)
        resp.raise_for_status()
        data = resp.json()
    except Exception as exc:
        logger.error("Fear & Greed API failed: %s", exc)
        return {}

    result: dict[str, tuple[int, str]] = {}
    for entry in data.get("data", []):
        d = _parse_date(entry["timestamp"])
        if start_date <= d <= end_date:
            result[d] = (int(entry["value"]), entry["value_classification"])

    logger.debug("Fear & Greed: %d entries fetched", len(result))
    return result

def _require_number(mapping: dict[str, Any], source_key: str, path: Path) -> float:
    if source_key not in mapping:
        raise ValueError(f"{path}: missing {source_key}")
    try:
        return float(mapping[source_key])
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{path}: {source_key} must be numeric") from exc

def _load_export(path: Path, export_date: str) -> dict[str, Any]:
    payload = json.loads(path.read_text())
    if not isinstance(payload, dict):
        raise ValueError(f"{path}: BDC payload must be an object")
    as_of = str(payload.get("as_of", ""))[:10]
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", as_of):
        raise ValueError(f"{path}: invalid as_of date")
    scores = payload.get("scores")
    regimes = payload.get("regime_probabilities")
    if not isinstance(scores, dict):
        raise ValueError(f"{path}: scores must be an object")
    if not isinstance(regimes, dict):
        raise ValueError(f"{path}: regime_probabilities must be an object")

    row: dict[str, Any] = {
        "export_date": export_date,
        "bdc_as_of_date": as_of,
    }
    for source_key, target_key in _SCORE_KEYS.items():
        row[target_key] = _require_number(scores, source_key, path)
    for source_key, target_key in _REGIME_KEYS.items():
        row[target_key] = _require_number(regimes, source_key, path)
    status_label = str(payload.get("status_label", "")).strip()
    row["status_code"] = status_label.split("—", 1)[0].strip()
    row["source_status"] = "ok"
    return row

def load_bdc_exports(inbox: Path = DEFAULT_BDC_INBOX) -> list[dict[str, Any]]:
    """Read validated dated exports from the market_data_collector-owned inbox only."""
    inbox = Path(inbox)
    if not inbox.exists():
        return []
    rows: list[dict[str, Any]] = []
    for path in sorted(inbox.glob("bdc_scores_*.json")):
        match = _DATED_EXPORT.fullmatch(path.name)
        if match is None:
            continue
        rows.append(_load_export(path, match.group(1)))
    return rows

def fetch_hashrate(start_date: str, end_date: str) -> dict[str, float | None]:
    """
    Fetch daily average miner hashrate in EH/s.

    Blockchain.info returns TH/s — we convert to EH/s (÷ 1_000_000).
    Returns: {date_str: eh_per_second_or_None}
    """
    try:
        resp = requests.get(
            f"{BASE_URL}/hash-rate",
            params={
                "start": start_date,
                "end": end_date,
                "format": "json",
                "sampled": "true",
                "metadata": "false",
                "cors": "true",
            },
            timeout=TIMEOUT,
        )
        resp.raise_for_status()
        data = resp.json()
    except Exception as exc:
        logger.error("Blockchain.info hashrate API failed: %s", exc)
        return {}

    result: dict[str, float | None] = {}
    for point in data.get("values", []):
        d = date.fromtimestamp(point["x"]).isoformat()
        if start_date <= d <= end_date:
            ths = point.get("y")
            result[d] = round(ths / 1_000_000, 4) if ths is not None else None

    logger.debug("Blockchain.info hashrate: %d rows", len(result))
    return result

def _parse_retry_after(header_value: str | None) -> float:
    """Return seconds to wait: header value + buffer, or default if header absent/unparseable."""
    if header_value is not None:
        try:
            return float(header_value) + _RETRY_AFTER_BUFFER
        except ValueError:
            pass
    return _RETRY_AFTER_DEFAULT

def _get_with_retry(url: str, params: dict) -> list:
    """GET with bounded 429 retries."""
    max_retries = max(0, int(settings.COINALYZE_MAX_RETRIES))
    for attempt in range(max_retries + 1):
        resp = requests.get(url, params=params, headers=_headers(), timeout=TIMEOUT)
        if resp.status_code == 429:
            try:
                body = resp.json()
            except Exception:
                body = resp.text[:300]
            retry_after_raw = resp.headers.get("Retry-After")
            sleep_time = _parse_retry_after(retry_after_raw)
            logger.warning(
                "Coinalyze 429 (attempt %d/%d) | Retry-After=%s → sleeping %.1fs | body=%s",
                attempt + 1, max_retries + 1, retry_after_raw, sleep_time, body,
            )
            if attempt < max_retries:
                time.sleep(sleep_time)
                continue
        resp.raise_for_status()
        return resp.json()
    return []

def fetch_open_interest_provenance(
    start_date: str,
    end_date: str,
    *,
    symbols: list[str] | None = None,
    basket_id: str | None = None,
) -> dict[str, dict]:
    """Return daily OI totals plus explicit immutable basket evidence.

    A null candle is unknown, never zero. Unexpected API symbols are retained
    nowhere: they cannot affect either aggregation or the persisted proof.
    """
    requested_symbols = list(symbols or settings.OI_SYMBOLS)
    requested_basket_id = basket_id or settings.OI_BASKET_ID
    try:
        data = _get_with_retry(
            f"{BASE_URL}/open-interest-history",
            params={
                "symbols": ",".join(requested_symbols),
                "interval": "daily",
                "from": _to_unix(start_date),
                "to": _to_unix(end_date) + 86400,
                "convert_to_usd": "true",
            },
        )
    except Exception as exc:
        logger.error("Coinalyze OI failed (%s–%s): %s", start_date, end_date, exc)
        return {}

    expected_symbols = set(requested_symbols)
    totals: dict[str, float] = {}
    observed_symbols: dict[str, set[str]] = {}
    for market in data:
        symbol = market.get("symbol")
        if symbol not in expected_symbols:
            logger.warning("Coinalyze OI returned unexpected symbol %r; ignoring it", symbol)
            continue
        for candle in market.get("history", []):
            d = datetime.fromtimestamp(candle["t"], tz=timezone.utc).date().isoformat()
            if start_date <= d <= end_date and candle.get("c") is not None:
                totals[d] = totals.get(d, 0.0) + float(candle["c"])
                observed_symbols.setdefault(d, set()).add(symbol)

    result: dict[str, dict] = {}
    for d, symbols in observed_symbols.items():
        ordered_observed = [symbol for symbol in requested_symbols if symbol in symbols]
        result[d] = {
            "value": round(totals[d], 2),
            "basket_id": requested_basket_id,
            "provider": "coinalyze",
            "endpoint": "/v1/open-interest-history",
            "interval": "daily",
            "field": "c",
            "convert_to_usd": True,
            "expected_symbols": list(requested_symbols),
            "observed_symbols": ordered_observed,
            "expected_symbol_count": len(requested_symbols),
            "observed_symbol_count": len(ordered_observed),
            "coverage_pct": round(len(ordered_observed) / len(requested_symbols) * 100, 2),
        }
    logger.debug("Coinalyze OI provenance: %d rows", len(result))
    return result

def fetch_open_interest_with_coverage(start_date: str, end_date: str) -> tuple[dict[str, float], dict[str, float]]:
    """Backward-compatible OI values and coverage projection."""
    provenance = fetch_open_interest_provenance(start_date, end_date)
    return (
        {day: item["value"] for day, item in provenance.items()},
        {day: item["coverage_pct"] for day, item in provenance.items()},
    )

def fetch_liquidations_provenance(start_date: str, end_date: str) -> dict[str, dict]:
    """Return fail-closed liquidation totals with daily basket evidence.

    This is a research contract. Unlike the legacy value-only helper below it
    emits no partial totals: a day is usable only if every configured market
    supplies both long and short USD candles.
    """
    try:
        data = _get_with_retry(
            f"{BASE_URL}/liquidation-history",
            params={
                "symbols": ",".join(settings.LIQ_SYMBOLS),
                "interval": "daily",
                "from": _to_unix(start_date),
                "to": _to_unix(end_date) + 86400,
                "convert_to_usd": "true",
            },
        )
    except Exception as exc:
        logger.error("Coinalyze liquidation provenance failed (%s–%s): %s", start_date, end_date, exc)
        return {}

    expected = tuple(settings.LIQ_SYMBOLS)
    observed: dict[str, set[str]] = {}
    incomplete: dict[str, set[str]] = {}
    longs: dict[str, float] = {}
    shorts: dict[str, float] = {}
    seen_days: set[str] = set()
    for market in data:
        symbol = market.get("symbol")
        if symbol not in expected:
            continue
        for candle in market.get("history", []):
            day = datetime.fromtimestamp(candle["t"], tz=timezone.utc).date().isoformat()
            if not start_date <= day <= end_date:
                continue
            seen_days.add(day)
            long_value, short_value = candle.get("l"), candle.get("s")
            if long_value is None or short_value is None:
                incomplete.setdefault(day, set()).add(symbol)
                continue
            observed.setdefault(day, set()).add(symbol)
            longs[day] = longs.get(day, 0.0) + float(long_value)
            shorts[day] = shorts.get(day, 0.0) + float(short_value)

    result: dict[str, dict] = {}
    for day in sorted(seen_days):
        observed_symbols = [
            symbol for symbol in expected
            if symbol in observed.get(day, set()) and symbol not in incomplete.get(day, set())
        ]
        complete = len(observed_symbols) == len(expected) and not incomplete.get(day)
        if complete:
            long_value = round(longs[day], 2)
            short_value = round(shorts[day], 2)
            total_value = round(long_value + short_value, 2)
        else:
            long_value = None
            short_value = None
            total_value = None
        result[day] = {
            "long": long_value,
            "short": short_value,
            "total": total_value,
            "basket_id": "coinalyze_btc_liquidation_basket_20260713_v1",
            "expected_symbols": list(expected),
            "observed_symbols": observed_symbols,
            "expected_symbol_count": len(expected),
            "observed_symbol_count": len(observed_symbols),
            "coverage_pct": round(len(observed_symbols) / len(expected) * 100, 2) if expected else 0.0,
            "provider": "coinalyze",
            "endpoint": "/v1/liquidation-history",
            "interval": "daily",
            "convert_to_usd": True,
        }
    return result

def fetch_liquidations(start_date: str, end_date: str) -> dict[str, dict[str, float | None]]:
    """Daily USD liquidation volumes summed across LIQ_SYMBOLS.

    `convert_to_usd=true` normalizes the mixed base-/quote-denominated
    contract set before aggregation. A missing/null candle field is unknown,
    not zero.
    """
    try:
        data = _get_with_retry(
            f"{BASE_URL}/liquidation-history",
            params={
                "symbols": ",".join(settings.LIQ_SYMBOLS),
                "interval": "daily",
                "from": _to_unix(start_date),
                "to": _to_unix(end_date) + 86400,
                # LIQ_SYMBOLS mixes BASE_ASSET- and QUOTE_ASSET-denominated
                # contracts. The API default is false; explicit conversion is
                # required before aggregating a value labelled USD.
                "convert_to_usd": "true",
            },
        )
    except Exception as exc:
        logger.error("Coinalyze liq failed (%s–%s): %s", start_date, end_date, exc)
        return {}

    longs: dict[str, float] = {}
    shorts: dict[str, float] = {}
    missing_longs: set[str] = set()
    missing_shorts: set[str] = set()
    # Same configured basket authority as fetch_liquidations_provenance.
    # Preserve the legacy side-level missingness contract, but never present
    # an absent market as a complete side (or total).
    expected = set(settings.LIQ_SYMBOLS)
    observed: dict[str, set[str]] = {}
    for market in data:
        symbol = market.get("symbol")
        if symbol not in expected:
            continue
        for candle in market.get("history", []):
            d = datetime.fromtimestamp(candle["t"], tz=timezone.utc).date().isoformat()
            if start_date <= d <= end_date:
                observed.setdefault(d, set()).add(symbol)
                l_val = candle.get("l")
                if l_val is None:
                    missing_longs.add(d)
                else:
                    longs[d] = longs.get(d, 0.0) + float(l_val)
                s_val = candle.get("s")
                if s_val is None:
                    missing_shorts.add(d)
                else:
                    shorts[d] = shorts.get(d, 0.0) + float(s_val)

    result: dict[str, dict[str, float | None]] = {}
    for d in set(longs) | set(shorts) | missing_longs | missing_shorts:
        if observed.get(d, set()) != expected:
            missing_longs.add(d)
            missing_shorts.add(d)
        l = None if d in missing_longs else round(longs.get(d, 0.0), 2)
        s = None if d in missing_shorts else round(shorts.get(d, 0.0), 2)
        result[d] = {"long": l, "short": s, "total": round(l + s, 2) if l is not None and s is not None else None}

    logger.debug("Coinalyze liq: %d rows", len(result))
    return result

def fetch_metrics(
    metrics: list[str],
    start_date: str,
    end_date: str,
    asset: str = "btc",
) -> dict[str, dict[str, float | None]]:
    """
    Fetch one or more daily metrics for a given asset.

    Returns: {date_str: {metric_name: value_or_None}}
    """
    url = f"{BASE_URL}/timeseries/asset-metrics"
    params = {
        "assets": asset,
        "metrics": ",".join(metrics),
        "start_time": f"{start_date}T00:00:00Z",
        "end_time": f"{end_date}T23:59:59Z",
        "frequency": "1d",
        "page_size": 1000,
    }

    result: dict[str, dict[str, float | None]] = {}
    page_params = dict(params)
    while True:
        try:
            resp = requests.get(url, params=page_params, timeout=TIMEOUT)
            resp.raise_for_status()
            data = resp.json()
        except Exception as exc:
            logger.error("CoinMetrics API failed: %s", exc)
            return {}

        for entry in data.get("data", []):
            d = entry["time"][:10]  # ISO8601 with nanoseconds — slice is safe
            day: dict[str, float | None] = {}
            for m in metrics:
                raw = entry.get(m)
                day[m] = float(raw) if raw is not None else None
            result[d] = day

        next_token = data.get("next_page_token")
        if not next_token:
            break
        page_params = {**params, "next_page_token": next_token}

    logger.debug("CoinMetrics %s: %d rows", ",".join(metrics), len(result))
    return result

def fetch_mvrv(start_date: str, end_date: str) -> dict[str, float | None]:
    """Fetch MVRV ratio. Returns {date_str: float_or_None}"""
    raw = fetch_metrics(["CapMVRVCur"], start_date, end_date)
    return {d: v.get("CapMVRVCur") for d, v in raw.items()}

def fetch_active_addresses(start_date: str, end_date: str) -> dict[str, float | None]:
    """Fetch active address count. Returns {date_str: float_or_None}"""
    raw = fetch_metrics(["AdrActCnt"], start_date, end_date)
    return {d: v.get("AdrActCnt") for d, v in raw.items()}

def _fetch_history(stablecoin_id: str) -> dict[str, float]:
    """
    Fetch full circulating history for one stablecoin.

    Returns: {date_str: circulating_usd}
    Uses /stablecoin/{id} → data["tokens"] for aggregate totals across all chains.
    """
    try:
        resp = requests.get(f"{BASE_URL}/stablecoin/{stablecoin_id}", timeout=TIMEOUT)
        resp.raise_for_status()
        data = resp.json()
    except Exception as exc:
        logger.error("DeFi Llama history for id=%s failed: %s", stablecoin_id, exc)
        return {}

    result: dict[str, float] = {}
    # "tokens" contains aggregate supply across all chains (correct level — not chainBalances)
    for entry in data.get("tokens", []):
        ts = entry.get("date")
        val = entry.get("totalCirculatingUSD", {}).get("peggedUSD")
        if ts and val is not None:
            d = date.fromtimestamp(int(ts)).isoformat()
            result[d] = float(val)

    return result

def fetch_historical(start_date: str, end_date: str) -> dict[str, float | None]:
    """
    Fetch USDT + USDC combined supply for a date range from full history.

    WARNING: loads full history (~2017–today) into memory per stablecoin.
    Only use for backfill, not daily jobs.

    Returns: {date_str: total_usd_or_None}
    """
    combined: dict[str, float] = {}

    for name, sid in STABLECOINS.items():
        logger.info("DeFi Llama: fetching full history for %s ...", name)
        history = _fetch_history(sid)
        for d, val in history.items():
            if start_date <= d <= end_date:
                combined[d] = combined.get(d, 0.0) + val
        time.sleep(1)  # polite delay between requests

    return {d: round(v, 2) if v else None for d, v in combined.items()}

def fetch_stablecoin_liquidity(
    start_date: str,
    end_date: str,
    backfill: bool = False,
) -> dict[str, float | None]:
    """
    Unified entry point.

    backfill=False (default): uses lightweight current endpoint (daily job).
    backfill=True: uses full history endpoint (slow, high memory).
    """
    if backfill:
        return fetch_historical(start_date, end_date)

    # Daily job: only need today's value
    val = fetch_current()
    today = date.today().isoformat()
    if val is not None and start_date <= today <= end_date:
        return {today: val}
    return {}

def _parse_date(s: str) -> str | None:
    s = s.strip()
    for fmt in ("%d %b %Y", "%d %B %Y"):
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            continue
    return None

def _parse_amount(s: str) -> float | None:
    """
    '655.3'  → 655_300_000.0
    '(95.1)' → -95_100_000.0
    '-'      → None
    """
    s = s.strip()
    if not s or s == "-":
        return None
    negative = s.startswith("(") and s.endswith(")")
    s = s.strip("()")
    try:
        val = float(s.replace(",", ""))
        return round((-val if negative else val) * 1_000_000, 2)
    except ValueError:
        return None

def _parse_markdown_table(text: str, start_date: str, end_date: str) -> dict[str, float | None]:
    result: dict[str, float | None] = {}
    in_table = False
    date_idx: int | None = None
    total_idx: int | None = None

    for line in text.splitlines():
        if not line.startswith("|"):
            if in_table:
                break
            continue

        cells = [c.strip() for c in line.strip("|").split("|")]
        if not in_table:
            lower = [c.lower() for c in cells]
            if "date" in lower and "total" in lower:
                date_idx = lower.index("date")
                total_idx = lower.index("total")
                in_table = True
            continue

        if all(set(c).issubset({"-", " ", ""}) for c in cells):
            continue
        if date_idx is None or total_idx is None or len(cells) <= max(date_idx, total_idx):
            continue

        d = _parse_date(cells[date_idx])
        if d and start_date <= d <= end_date:
            result[d] = _parse_amount(cells[total_idx])
    return result

def _parse_line_layout(text: str, start_date: str, end_date: str) -> dict[str, float | None]:
    """Parse Jina's current layout: one non-empty field per line."""
    items = [line.strip() for line in text.splitlines() if line.strip()]
    for index, item in enumerate(items):
        if item != "Date":
            continue

        first_row = next((i for i in range(index + 1, len(items)) if _parse_date(items[i])), None)
        if first_row is None:
            continue
        headers = items[index + 1:first_row]
        lower = [header.lower() for header in headers]
        if "total" not in lower:
            continue

        width = len(headers)
        total_idx = lower.index("total")
        result: dict[str, float | None] = {}
        for row_start in range(first_row, len(items)):
            d = _parse_date(items[row_start])
            if not d:
                continue
            values = items[row_start + 1:row_start + 1 + width]
            if len(values) != width:
                continue
            if start_date <= d <= end_date:
                result[d] = _parse_amount(values[total_idx])
        return result
    return {}

def parse_etf_inflows(text: str, start_date: str, end_date: str) -> dict[str, float | None]:
    """Parse either observed Jina rendering of Farside's all-data page."""
    return _parse_markdown_table(text, start_date, end_date) or _parse_line_layout(
        text, start_date, end_date
    )

def fetch_etf_inflows(start_date: str, end_date: str) -> dict[str, float | None]:
    """
    Fetch net daily BTC ETF inflows in USD from farside.co.uk.

    Returns: {date_str: net_flow_usd_or_None}
    """
    try:
        resp = requests.get(FARSIDE_URL, timeout=TIMEOUT)
        resp.raise_for_status()
        text = resp.text
    except Exception as exc:
        logger.warning("ETF flows (farside via Jina) unavailable: %s", exc)
        return {}

    result = parse_etf_inflows(text, start_date, end_date)
    logger.debug("ETF flows (farside): %d rows", len(result))
    return result

def _parse_farside_date(s: str) -> str | None:
    """Convert '11 Jan 2024' to '2024-01-11'."""
    s = s.strip()
    for fmt in ("%d %b %Y", "%d %B %Y"):
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            continue
    return None

def fetch_etf_inflows(start_date: str, end_date: str) -> dict[str, float | None]:
    """
    Fetch net daily BTC ETF inflows in USD from farside.co.uk.

    Returns: {date_str: net_flow_usd_or_None}
    Values are in USD (farside source is in USD millions).
    """
    try:
        resp = requests.get(FARSIDE_URL, timeout=TIMEOUT)
        resp.raise_for_status()
        text = resp.text
    except Exception as exc:
        logger.warning("ETF Tracker (farside via Jina) unavailable: %s", exc)
        return {}

    result: dict[str, float | None] = {}

    # Find markdown table rows: | date | ... | total |
    # Header line contains "Date" and "Total"
    in_table = False
    date_idx = None
    total_idx = None

    for line in text.splitlines():
        if not line.startswith("|"):
            if in_table:
                break  # table ended
            continue

        cells = [c.strip() for c in line.strip("|").split("|")]

        # Detect header row
        if not in_table:
            lower = [c.lower() for c in cells]
            if "date" in lower and "total" in lower:
                date_idx = lower.index("date")
                total_idx = lower.index("total")
                in_table = True
            continue

        # Skip separator rows (--- lines)
        if all(set(c).issubset({"-", " ", ""}) for c in cells):
            continue

        if date_idx is None or total_idx is None or len(cells) <= max(date_idx, total_idx):
            continue

        d = _parse_farside_date(cells[date_idx])
        if d and start_date <= d <= end_date:
            result[d] = _parse_amount(cells[total_idx])

    logger.debug("ETF Tracker (farside): %d rows parsed", len(result))
    return result

def fetch_fear_greed(start_date: str, end_date: str) -> dict[str, int]:
    """
    Fetch Fear & Greed index values for a date range.

    Returns: {date_str: value_int}
    API delivers data newest-first; backfill uses limit=3000 (max available ~2018-02-01).
    """
    days_needed = (date.fromisoformat(end_date) - date.fromisoformat(start_date)).days + 3
    # Alternative.me caps at 3000; clamp for large backfills
    limit = min(days_needed, 3000)

    try:
        resp = requests.get(BASE_URL, params={"limit": limit}, timeout=TIMEOUT)
        resp.raise_for_status()
        data = resp.json()
    except Exception as exc:
        logger.error("Fear & Greed API failed: %s", exc)
        return {}

    result: dict[str, int] = {}
    for entry in data.get("data", []):
        d = datetime.fromtimestamp(int(entry["timestamp"]), tz=timezone.utc).date().isoformat()
        if start_date <= d <= end_date:
            result[d] = int(entry["value"])

    logger.debug("Fear & Greed: %d entries", len(result))
    return result

def _cell_text(cell: ET.Element, shared_strings: list[str]) -> str:
    inline = cell.find("x:is", _XML_NS)
    if inline is not None:
        return "".join(node.text or "" for node in inline.iterfind(".//x:t", _XML_NS)).strip()
    value = cell.find("x:v", _XML_NS)
    raw = value.text.strip() if value is not None and value.text is not None else ""
    if cell.get("t") == "s":
        try:
            index = int(raw)
            if index < 0:
                raise ValueError("negative index")
            return shared_strings[index].strip()
        except (ValueError, IndexError) as exc:
            raise ValueError("invalid FINRA shared-string index") from exc
    return raw

def parse_finra_margin_xlsx(blob: bytes) -> list[tuple[date, float]]:
    """Parse the fixed FINRA workbook contract and reject silent schema drift."""
    try:
        with zipfile.ZipFile(io.BytesIO(blob)) as workbook:
            xml = workbook.read("xl/worksheets/sheet1.xml")
            shared_xml = (workbook.read("xl/sharedStrings.xml")
                          if "xl/sharedStrings.xml" in workbook.namelist() else None)
        # Input is accepted only from the fixed FINRA HTTPS endpoint, but still
        # reject XML entity/DTD constructs and unreasonable expansion surfaces
        # before stdlib parsing (defusedxml is not a project dependency).
        for label, part in (("worksheet", xml), ("shared strings", shared_xml)):
            if part is not None and (len(part) > 20_000_000 or b"<!DOCTYPE" in part or b"<!ENTITY" in part):
                raise ValueError(f"unsafe FINRA {label} XML")
        root = ET.fromstring(xml)
        shared_strings = []
        if shared_xml is not None:
            shared_strings = [
                "".join(node.text or "" for node in item.iterfind(".//x:t", _XML_NS))
                for item in ET.fromstring(shared_xml).findall("x:si", _XML_NS)
            ]
    except (zipfile.BadZipFile, KeyError, ET.ParseError) as exc:
        raise ValueError("invalid FINRA XLSX workbook") from exc

    sheet_data = root.find("x:sheetData", _XML_NS)
    if sheet_data is None:
        raise ValueError("FINRA XLSX schema missing sheetData")

    parsed_rows: list[dict[str, str]] = []
    for row in sheet_data.findall("x:row", _XML_NS):
        cells: dict[str, str] = {}
        for cell in row.findall("x:c", _XML_NS):
            ref = str(cell.get("r", ""))
            column = "".join(ch for ch in ref if ch.isalpha())
            if column:
                cells[column] = _cell_text(cell, shared_strings)
        if cells:
            parsed_rows.append(cells)
    if not parsed_rows:
        raise ValueError("FINRA XLSX contains no rows")

    header = parsed_rows[0]
    if header.get("A") != "Year-Month" or "Debit Balances" not in header.get("B", ""):
        raise ValueError(f"FINRA XLSX header mismatch: {header!r}")

    observations: list[tuple[date, float]] = []
    seen: set[date] = set()
    for row in parsed_rows[1:]:
        raw_month = row.get("A", "")
        raw_debit = row.get("B", "")
        if not raw_month and not raw_debit:
            continue
        try:
            month = datetime.strptime(raw_month, "%Y-%m").date().replace(day=1)
            debit = float(raw_debit.replace(",", ""))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"invalid FINRA margin row: {row!r}") from exc
        if month in seen:
            raise ValueError(f"duplicate FINRA margin month: {month.isoformat()}")
        seen.add(month)
        observations.append((month, debit))
    if not observations:
        raise ValueError("FINRA XLSX contains no numeric margin observations")
    return sorted(observations)

def fetch_finra_margin(timeout: int = 30) -> list[tuple[date, float]]:
    request = urllib.request.Request(
        FINRA_MARGIN_XLSX_URL,
        headers={"User-Agent": "market_data_collector/macro-data-v1"},
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        blob = response.read()
    return parse_finra_margin_xlsx(blob)

def load_verified_archive(
    archive_path: Path = DEFAULT_ARCHIVE_PATH,
    metadata_path: Path = DEFAULT_METADATA_PATH,
) -> list[tuple[date, float]]:
    """Load the committed HY-OAS archive only after byte and span validation."""
    archive_path = Path(archive_path)
    metadata_path = Path(metadata_path)
    metadata = json.loads(metadata_path.read_text())
    actual_sha256 = hashlib.sha256(archive_path.read_bytes()).hexdigest()
    if actual_sha256 != metadata.get("sha256"):
        raise ValueError(
            f"HY-OAS archive checksum mismatch: expected={metadata.get('sha256')} "
            f"actual={actual_sha256}"
        )

    rows: list[tuple[date, float]] = []
    with archive_path.open(newline="") as handle:
        reader = csv.DictReader(handle)
        if not reader.fieldnames or "DATE" not in reader.fieldnames or SERIES_ID not in reader.fieldnames:
            raise ValueError("HY-OAS archive schema mismatch")
        for row in reader:
            raw = row.get(SERIES_ID, "")
            if raw in ("", ".", None):
                continue
            try:
                rows.append((_parse_date(str(row.get("DATE", ""))), float(raw)))
            except (TypeError, ValueError) as exc:
                raise ValueError(f"invalid HY-OAS archive row: {row!r}") from exc

    rows.sort()
    if not rows:
        raise ValueError("HY-OAS archive contains no numeric observations")
    if rows[0][0].isoformat() != metadata.get("coverage_start"):
        raise ValueError("HY-OAS archive coverage_start mismatch")
    if rows[-1][0].isoformat() != metadata.get("coverage_end"):
        raise ValueError("HY-OAS archive coverage_end mismatch")
    return rows

def merge_archive_with_fred(
    archive_rows: Iterable[tuple[date, float]],
    fred_rows: Iterable[tuple[date, float]],
) -> list[tuple[date, float, str]]:
    """Merge observations by date; current FRED wins overlap and gaps stay absent."""
    merged: dict[date, tuple[float, str]] = {
        observation_date: (float(value), "archive")
        for observation_date, value in archive_rows
    }
    for observation_date, value in fred_rows:
        merged[observation_date] = (float(value), "current_fred")
    return [
        (observation_date, value, regime)
        for observation_date, (value, regime) in sorted(merged.items())
    ]

def fetch_fred_series(
    series_id: str,
    observation_start: str,
    observation_end: str,
    timeout: int = 30,
) -> list[tuple[date, float]]:
    """Fetch one explicit FRED history and fail closed on schema/empty drift."""
    if series_id not in MACRO_FRED_SERIES:
        raise ValueError(f"unsupported Macro FRED series: {series_id}")
    response = requests.get(
        FRED_GRAPH_CSV_URL,
        params={"id": series_id, "cosd": observation_start, "coed": observation_end},
        timeout=timeout,
    )
    response.raise_for_status()
    text = response.content.decode("utf-8", errors="strict")

    reader = csv.DictReader(text.splitlines())
    if not reader.fieldnames or "observation_date" not in reader.fieldnames or series_id not in reader.fieldnames:
        raise ValueError(
            f"FRED schema mismatch for {series_id}: fields={reader.fieldnames!r}"
        )

    rows: list[tuple[date, float]] = []
    for row in reader:
        raw = row.get(series_id)
        if raw in (None, "", "."):
            continue
        try:
            observation_date = datetime.strptime(
                str(row.get("observation_date", ""))[:10], "%Y-%m-%d"
            ).date()
            rows.append((observation_date, float(raw)))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"invalid FRED row for {series_id}: {row!r}") from exc
    if not rows:
        raise ValueError(f"FRED {series_id} returned no numeric observations")
    return sorted(rows)

def session_close(day: date):
    """Expected scheduled close; missing quotes never move an anchor."""
    if day.weekday()>4 or not _NYSEHolidays().holidays(start=day,end=day).empty:
        return None
    early = ((day.month,day.day) in ((7,3),(12,24))
             or (day.month==11 and day.weekday()==4 and 23<=day.day<=29))
    return datetime(day.year,day.month,day.day,13 if early else 16,tzinfo=ZoneInfo('America/New_York'))

def _scalar(val) -> float | None:
    """Extract scalar from potentially Series/array value (fixes yfinance FutureWarning)."""
    if val is None:
        return None
    if isinstance(val, pd.Series):
        if val.empty:
            return None
        val = val.iloc[0]
    try:
        f = float(val)
        return None if math.isnan(f) else f
    except (TypeError, ValueError):
        return None

def fetch_ohlcv(ticker: str, start_date: str, end_date: str) -> dict[str, dict[str, float]]:
    """
    Fetch daily OHLCV for a single ticker.

    Returns: {date_str: {"Close": x, "High": x, "Low": x, "Open": x, "Volume": x}}
    end_date is inclusive.
    """
    end_dt = (date.fromisoformat(end_date) + timedelta(days=1)).isoformat()
    try:
        df = yf.download(
            ticker,
            start=start_date,
            end=end_dt,
            progress=False,
            auto_adjust=True,
        )
    except Exception as exc:
        logger.error("Yahoo Finance download failed for %s: %s", ticker, exc)
        return {}

    if df.empty:
        logger.warning("Yahoo Finance returned empty data for %s (%s → %s)", ticker, start_date, end_date)
        return {}

    # Flatten MultiIndex columns if present
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = df.columns.get_level_values(0)

    result: dict[str, dict[str, float]] = {}
    for ts, row in df.iterrows():
        date_str = ts.date().isoformat()
        values: dict[str, float] = {}
        for key in OHLCV_KEYS:
            val = _scalar(row.get(key))
            if val is not None:
                values[key] = round(val, 8)
        if values:
            result[date_str] = values

    logger.debug("Yahoo Finance %s: %d rows returned", ticker, len(result))
    return result

def fetch_multi_close(
    symbols: list[str],
    start_date: str,
    end_date: str,
    key_by_symbol: dict[str, str] | None = None,
    *, auto_adjust: bool = True,
) -> dict[str, dict[str, float]]:
    """
    Fetch daily close prices for multiple symbols in one call.

    key_by_symbol: map {yahoo_symbol: output_key_name}
    Returns: {date_str: {key: close_price}}
    """
    if key_by_symbol is None:
        key_by_symbol = {s: s for s in symbols}

    end_dt = (date.fromisoformat(end_date) + timedelta(days=1)).isoformat()
    try:
        df = yf.download(
            symbols,
            start=start_date,
            end=end_dt,
            progress=False,
            auto_adjust=auto_adjust,
        )
    except Exception as exc:
        logger.error("Yahoo Finance multi-download failed: %s", exc)
        return {}

    if df.empty:
        logger.warning("Yahoo Finance multi-download returned empty data")
        return {}

    # Extract Close prices
    if isinstance(df.columns, pd.MultiIndex):
        close_df = df["Close"]
    else:
        close_df = df[["Close"]]

    result: dict[str, dict[str, float]] = {}
    for ts, row in close_df.iterrows():
        date_str = ts.date().isoformat()
        day_data: dict[str, float] = {}
        for symbol in symbols:
            val = _scalar(row.get(symbol))
            if val is not None:
                col_key = key_by_symbol.get(symbol, symbol)
                day_data[col_key] = round(val, 6)
        if day_data:
            result[date_str] = day_data

    logger.debug("Yahoo Finance multi: %d days returned", len(result))
    return result

def reconcile_db_source_status(existing: list, incoming: list, merged: list) -> list:
    """Mark a source `kept_prior` when merge-safe upsert retained its old DB cell."""
    status_idx = DB_COLUMNS.index("source_status_json")
    try:
        status = json.loads(incoming[status_idx] or "{}")
    except (TypeError, json.JSONDecodeError):
        return merged

    for source, columns in DB_STATUS_SOURCE_COLUMNS.items():
        if status.get(source) != "missing":
            continue
        indexes = [DB_COLUMNS.index(column) for column in columns]
        retained = all(
            _is_empty(incoming[idx]) and not _is_empty(existing[idx]) and merged[idx] == existing[idx]
            for idx in indexes
        )
        if retained:
            status[source] = "kept_prior"

    reconciled = list(merged)
    reconciled[status_idx] = json.dumps(status, sort_keys=True)
    return reconciled

def reconcile_macro_source_status(existing: list, incoming: list, merged: list) -> list:
    """Replace or retain complete Macro families and expose retained values."""
    status_idx = MACRO_DATA_COLUMNS.index("source_status_json")
    version_idx = MACRO_DATA_COLUMNS.index("calculation_version_json")
    try:
        status = json.loads(incoming[status_idx] or "{}")
    except (TypeError, json.JSONDecodeError):
        return merged
    try:
        existing_versions = json.loads(existing[version_idx] or "{}")
        incoming_versions = json.loads(incoming[version_idx] or "{}")
    except (TypeError, json.JSONDecodeError):
        existing_versions = {}
        incoming_versions = {}
    reconciled = list(merged)
    reconciled_versions = dict(existing_versions)
    for family, columns in MACRO_STATUS_FAMILY_COLUMNS.items():
        indexes = [MACRO_DATA_COLUMNS.index(column) for column in columns]
        family_status = status.get(family)
        incoming_empty = all(_is_empty(incoming[index]) for index in indexes)
        if family_status == "missing" and incoming_empty:
            retained = any(not _is_empty(existing[index]) for index in indexes)
            for index in indexes:
                reconciled[index] = existing[index]
            if retained:
                status[family] = "kept_prior"
            continue
        if family_status not in (None, "missing", "kept_prior"):
            for index in indexes:
                reconciled[index] = incoming[index]
            version_key = MACRO_FAMILY_VERSION_KEYS[family]
            if version_key in incoming_versions:
                reconciled_versions[version_key] = incoming_versions[version_key]
            else:
                reconciled_versions.pop(version_key, None)
    reconciled[status_idx] = json.dumps(status, sort_keys=True)
    reconciled[version_idx] = json.dumps(reconciled_versions, sort_keys=True)
    return reconciled

def assert_macro_data_header(sheet) -> list[list]:
    values = sheet.get_all_values()
    actual = values[0] if values else []
    if actual != MACRO_DATA_COLUMNS:
        raise MacroDataSchemaError(
            "MACRO_DATA header mismatch; refusing incremental write. "
            f"expected={MACRO_DATA_COLUMNS!r}, actual={actual!r}."
        )
    return values

def assert_market_data_header(sheet) -> None:
    """Fail closed before a positional daily upsert hits a stale MARKET_DATA schema."""
    values = sheet.get_all_values()
    actual = values[0] if values else []
    if actual != MARKET_DATA_HEADER:
        raise MarketDataSchemaError(
            "MARKET_DATA header mismatch; refusing incremental write. "
            f"expected={MARKET_DATA_HEADER!r}, actual={actual!r}. "
            "Run a reviewed, explicit schema migration/full backfill before retrying."
        )

def _latest_completed_daily_date() -> str:
    # Daily close rows should represent completed calendar days, not the
    # current in-progress BTC candle.
    return (date.today() - timedelta(days=1)).isoformat()

def _fetch_yfinance_close(symbol: str, start_date: str, end_date: str) -> dict[str, float | None]:
    if not _HAS_YFINANCE:
        logger.warning("yfinance not installed — %s data unavailable", symbol)
        return {}
    try:
        ticker = yf.Ticker(symbol)
        # yfinance end is exclusive; add one day so today's row can appear if available.
        yf_end = (date.fromisoformat(end_date) + timedelta(days=1)).isoformat()
        auto_adjust = symbol not in _RAW_PRICE_SYMBOLS and symbol not in SECTOR_SYMBOL_MAP
        hist = ticker.history(start=start_date, end=yf_end, auto_adjust=auto_adjust)
        if hist.empty:
            logger.warning("yfinance %s returned no rows", symbol)
            return {}
        return {
            str(idx.date()): round(float(row["Close"]), 6)
            for idx, row in hist.iterrows()
            if pd.notna(row.get("Close"))
        }
    except Exception as exc:
        logger.error("yfinance %s failed: %s", symbol, exc)
        return {}

def _fetch_mstr_close(start_date: str, end_date: str) -> dict[str, float | None]:
    data = _fetch_yfinance_close("MSTR", start_date, end_date)
    return {d: (round(v, 2) if v is not None else None) for d, v in data.items()}

def _build_macro_data_rows(
    now_utc: str,
    start_override: str | None = None,
    write_start: str | None = None,
    end_date: str | None = None,
    allow_partial: bool = False,
    failures: list[str] | None = None,
) -> list[list[object]]:
    """Fetch Macro histories; full builds fail closed, daily builds degrade by family."""
    target_end = end_date or END_DATE

    def attempt(label: str, operation):
        try:
            result = operation()
            if not result:
                raise RuntimeError(f"{label} produced no data")
            return result
        except Exception:
            if not allow_partial:
                raise
            if failures is not None:
                failures.append(label)
            logger.exception("MACRO_DATA daily family input unavailable: %s", label)
            return []

    def attempt_family(label: str, operation) -> dict[date, dict[str, object]]:
        try:
            result = operation()
            if not result:
                raise RuntimeError(f"{label} produced no data")
            return result
        except Exception:
            if not allow_partial:
                raise
            if failures is not None:
                failures.append(label)
            logger.exception("MACRO_DATA daily family unavailable: %s", label)
            return {}

    finra_rows = attempt("FINRA", fetch_finra_margin)
    cpi_rows = attempt(
        "CPIAUCSL",
        lambda: fetch_fred_series("CPIAUCSL", start_override or "1940-01-01", target_end),
    )
    nfci_rows = attempt(
        "NFCILEVERAGE",
        lambda: fetch_fred_series("NFCILEVERAGE", "1970-01-01", target_end),
    )
    walcl_rows = attempt(
        "WALCL", lambda: fetch_fred_series("WALCL", start_override or "1990-01-01", target_end)
    )
    tga_rows = attempt(
        "WTREGEN", lambda: fetch_fred_series("WTREGEN", start_override or "1990-01-01", target_end)
    )
    rrp_rows = attempt(
        "RRPONTSYD",
        lambda: fetch_fred_series("RRPONTSYD", start_override or "1990-01-01", target_end),
    )
    current_hy_oas = attempt(
        "BAMLH0A0HYM2 current",
        lambda: fetch_fred_series("BAMLH0A0HYM2", start_override or "1990-01-01", target_end),
    )
    archive_hy_oas = attempt("BAMLH0A0HYM2 archive", load_verified_archive)
    merged_hy_oas = (
        attempt(
            "BAMLH0A0HYM2 merge",
            lambda: merge_archive_with_fred(archive_hy_oas, current_hy_oas),
        )
        if archive_hy_oas and current_hy_oas
        else []
    )

    price_start = start_override or "1990-01-01"

    def fetch_spx():
        mapping = _fetch_yfinance_close("^GSPC", price_start, target_end)
        if not mapping:
            mapping = _fetch_yfinance_close("SPY", price_start, target_end)
        return [
            (date.fromisoformat(day), float(value))
            for day, value in mapping.items()
            if value is not None
        ]

    spx_rows = attempt("SPX/SPY", fetch_spx)
    bdc_exports = attempt("BDC inbox", load_bdc_exports)

    finra_family = (
        attempt_family("FINRA family", lambda: build_finra_family(finra_rows, cpi_rows, spx_rows))
        if finra_rows and cpi_rows and spx_rows
        else {}
    )
    nfci_family = attempt_family("NFCI family", lambda: build_nfci_family(nfci_rows)) if nfci_rows else {}
    liquidity_family = (
        attempt_family(
            "liquidity family",
            lambda: build_liquidity_family(walcl_rows, tga_rows, rrp_rows),
        )
        if walcl_rows and tga_rows and rrp_rows
        else {}
    )
    hy_oas_family = (
        attempt_family("HY-OAS family", lambda: build_hy_oas_family(merged_hy_oas, spx_rows))
        if merged_hy_oas and spx_rows
        else {}
    )
    bdc_family = attempt_family("BDC family", lambda: build_bdc_family(bdc_exports)) if bdc_exports else {}

    families = (finra_family, nfci_family, liquidity_family, hy_oas_family, bdc_family)
    rows: list[list[object]]
    if allow_partial and not any(families):
        rows = [list(MACRO_DATA_COLUMNS)]
    else:
        rows = build_macro_rows(
            finra=finra_family,
            nfci=nfci_family,
            liquidity=liquidity_family,
            hy_oas=hy_oas_family,
            bdc=bdc_family,
            updated_at_utc=now_utc,
        )
    if not allow_partial and start_override is None and write_start is None:
        validate_backfill_report(build_backfill_report(rows))
    if write_start:
        rows = [rows[0], *[row for row in rows[1:] if str(row[0]) >= write_start]]
    validate_macro_rows(rows)
    return rows

def attempt(label: str, operation):
    try:
        result = operation()
        if not result:
            raise RuntimeError(f"{label} produced no data")
        return result
    except Exception:
        if not allow_partial:
            raise
        if failures is not None:
            failures.append(label)
        logger.exception("MACRO_DATA daily family input unavailable: %s", label)
        return []

def attempt_family(label: str, operation) -> dict[date, dict[str, object]]:
    try:
        result = operation()
        if not result:
            raise RuntimeError(f"{label} produced no data")
        return result
    except Exception:
        if not allow_partial:
            raise
        if failures is not None:
            failures.append(label)
        logger.exception("MACRO_DATA daily family unavailable: %s", label)
        return {}

def fetch_spx():
    mapping = _fetch_yfinance_close("^GSPC", price_start, target_end)
    if not mapping:
        mapping = _fetch_yfinance_close("SPY", price_start, target_end)
    return [
        (date.fromisoformat(day), float(value))
        for day, value in mapping.items()
        if value is not None
    ]

def run(dry_run: bool = False, sheets: set[str] | None = None) -> dict[str, object] | None:
    """Manual full rebuild, optionally restricted to explicit target tabs."""
    targets = sheets if sheets is not None else {DB_SHEET_NAME, MARKET_DATA_SHEET_NAME}
    allowed = {DB_SHEET_NAME, MARKET_DATA_SHEET_NAME, MACRO_DATA_SHEET_NAME}
    unknown = targets - allowed
    if unknown:
        raise ValueError(f"unknown backfill target sheets: {sorted(unknown)}")
    logger.info("=== Full Backfill START (dry_run=%s, sheets=%s) ===", dry_run, sorted(targets))
    now_utc = datetime.now(tz=timezone.utc).isoformat()
    builders = {
        DB_SHEET_NAME: _build_db_rows,
        MARKET_DATA_SHEET_NAME: _build_market_data_rows,
        MACRO_DATA_SHEET_NAME: _build_macro_data_rows,
    }
    built_rows: dict[str, list[list[object]]] = {}
    for sheet_name in (DB_SHEET_NAME, MARKET_DATA_SHEET_NAME, MACRO_DATA_SHEET_NAME):
        if sheet_name in targets:
            built_rows[sheet_name] = builders[sheet_name](now_utc)

    macro_report = (
        build_backfill_report(built_rows[MACRO_DATA_SHEET_NAME])
        if MACRO_DATA_SHEET_NAME in built_rows
        else None
    )

    for sheet_name in (DB_SHEET_NAME, MARKET_DATA_SHEET_NAME, MACRO_DATA_SHEET_NAME):
        if sheet_name not in targets:
            continue
        rows = built_rows[sheet_name]
        logger.info("Writing %d data rows to %s sheet...", len(rows) - 1, sheet_name)
        if not dry_run:
            if sheet_name == MACRO_DATA_SHEET_NAME:
                batch_write(
                    get_or_create_sheet(
                        sheet_name,
                        rows=max(100, len(rows)),
                        cols=len(MACRO_DATA_COLUMNS),
                    ),
                    rows,
                    dry_run=False,
                    column_types=MACRO_DATA_COLUMN_TYPES,
                )
            else:
                batch_write(get_sheet(sheet_name), rows, dry_run=False)
        else:
            logger.info("[dry-run] Would full-write %d %s rows", len(rows) - 1, sheet_name)

    if macro_report is not None:
        logger.info("MACRO_DATA backfill report: %s", json.dumps(macro_report, sort_keys=True))
    logger.info("=== Full Backfill DONE%s ===", " (dry-run)" if dry_run else "")
    return macro_report

def compute_200w_ma(btc_price: pd.Series) -> pd.Series:
    """Return the 200-week MA from exact UTC Sunday closes, carried to later days."""
    prices = btc_price.copy()
    prices.index = pd.DatetimeIndex(prices.index)
    sunday = prices[prices.index.weekday == 6]
    if sunday.empty:
        return pd.Series(index=prices.index, dtype=float)
    expected = pd.date_range(sunday.index.min(), sunday.index.max(), freq="W-SUN")
    weekly = sunday.reindex(expected)
    weekly_ma = weekly.rolling(200, min_periods=200).mean()
    return weekly_ma.reindex(prices.index, method="ffill")

def annotate_data_contracts(df: pd.DataFrame) -> pd.DataFrame:
    """Write OD-8/OD-14 markers into source_status_json without new schema.

    - OD-8: `btc_ma_source` records whether the MA/ratio input used the canonical
      Coinbase close, the visible Binance fallback, or had no BTC price.
    - OD-14: `partial_windows` lists the emitted min_periods=1 rolling metrics
      whose trailing window is not yet full, so no consumer reads a short-window
      value as a full 7d/30d metric.

    Both markers ride the already persisted, already consumed source_status_json
    column; legacy rows without the keys stay fail-closed at the consumer.
    """
    n = len(df)
    if "source_status_json" in df.columns:
        raw_status = df["source_status_json"].tolist()
    else:
        raw_status = ["{}"] * n

    # OD-8: which BTC price fed the MA/ratio input, per row.
    coinbase_present = df["btc_coinbase_close"].notna().to_numpy()
    binance_present = df["btc_binance_close"].notna().to_numpy()
    ma_source = np.where(
        coinbase_present, "coinbase",
        np.where(binance_present, "binance_fallback", "missing"),
    )

    # OD-14: trailing observation counts per rolling metric.
    obs_counts = {}
    metric_values = {}
    for metric, (source_col, window) in PARTIAL_WINDOW_METRICS.items():
        if metric not in df.columns or source_col not in df.columns:
            continue
        obs_counts[metric] = (
            pd.Series(df[source_col].notna().to_numpy(), index=pd.to_datetime(df["date"]))
            .rolling(f"{window}D", min_periods=1).sum().to_numpy()
        )
        metric_values[metric] = df[metric].to_numpy()

    new_status = []
    for i in range(n):
        try:
            status = json.loads(raw_status[i] or "{}")
            if not isinstance(status, dict):
                status = {}
        except (TypeError, ValueError, json.JSONDecodeError):
            status = {}

        partials = sorted(
            metric
            for metric, (_source_col, window) in PARTIAL_WINDOW_METRICS.items()
            if metric in obs_counts
            and pd.notna(metric_values[metric][i])
            and obs_counts[metric][i] < window
        )
        status["partial_windows"] = partials
        status["btc_ma_source"] = str(ma_source[i])
        new_status.append(json.dumps(status, sort_keys=True))

    df["source_status_json"] = new_status
    return df

def monthly_last(rows: Iterable[tuple[date, float]]) -> list[tuple[date, float]]:
    by_month: dict[tuple[int, int], tuple[date, float]] = {}
    for observation_date, value in rows:
        key = (observation_date.year, observation_date.month)
        if key not in by_month or observation_date > by_month[key][0]:
            by_month[key] = (observation_date, float(value))
    return [by_month[key] for key in sorted(by_month)]

def _has_contiguous_months(rows: list[tuple], index: int, lookback: int) -> bool:
    if index < lookback:
        return False
    window = rows[index - lookback : index + 1]
    return all(
        (right[0].year * 12 + right[0].month)
        - (left[0].year * 12 + left[0].month)
        == 1
        for left, right in zip(window, window[1:])
    )

def _has_contiguous_month_keys(
    keys: list[tuple[int, int]], index: int, lookback: int
) -> bool:
    if index < lookback:
        return False
    window = keys[index - lookback : index + 1]
    return all(
        (right[0] * 12 + right[1]) - (left[0] * 12 + left[1]) == 1
        for left, right in zip(window, window[1:])
    )

def _percentile_to_date(rows: list[tuple[date, float]], index: int) -> float:
    current = rows[index][1]
    values = [value for _, value in rows[: index + 1]]
    return round(100.0 * sum(value <= current for value in values) / len(values), 1)

def build_nfci_family(
    rows: Iterable[tuple[date, float]],
) -> dict[date, dict[str, object]]:
    raw = sorted((observation_date, float(value)) for observation_date, value in rows)
    monthly = monthly_last(raw)
    output: dict[date, dict[str, object]] = {
        observation_date: {"nfci_leverage": value}
        for observation_date, value in raw
    }
    delta_series: list[tuple[date, float]] = []
    for index, (observation_date, value) in enumerate(monthly):
        record: dict[str, object] = {"nfci_leverage": value}
        if _has_contiguous_months(monthly, index, 3):
            delta_value = round(value - monthly[index - 3][1], 6)
            delta_series.append((observation_date, delta_value))
            delta_index = len(delta_series) - 1
            percentile = _percentile_to_date(delta_series, delta_index)
            record.update(
                {
                    "nfci_leverage_delta_3m": delta_value,
                    "nfci_leverage_percentile": percentile,
                    "nfci_leverage_warning": bool(
                        delta_index >= 6 and percentile >= 85.0 and delta_value > 0
                    ),
                }
            )
        output[observation_date] = record
    return output

def build_liquidity_family(
    walcl_rows: Iterable[tuple[date, float]],
    tga_rows: Iterable[tuple[date, float]],
    rrp_rows: Iterable[tuple[date, float]],
) -> dict[date, dict[str, object]]:
    """Build the reviewed 3M component-agreement liquidity warning."""
    raw_walcl = sorted((d, float(value)) for d, value in walcl_rows)
    raw_tga = sorted((d, float(value)) for d, value in tga_rows)
    raw_rrp = sorted((d, float(value)) for d, value in rrp_rows)
    walcl = {(d.year, d.month): (d, value) for d, value in monthly_last(raw_walcl)}
    tga = {(d.year, d.month): (d, value) for d, value in monthly_last(raw_tga)}
    rrp = {(d.year, d.month): (d, value) for d, value in monthly_last(raw_rrp)}
    keys = sorted(set(walcl) & set(tga) & set(rrp))
    output: dict[date, dict[str, object]] = {}
    for observation_date, value in raw_walcl:
        output.setdefault(observation_date, {})["fed_walcl"] = value
    for observation_date, value in raw_tga:
        output.setdefault(observation_date, {})["fed_tga_wtregen"] = value
    for observation_date, value in raw_rrp:
        output.setdefault(observation_date, {})["fed_rrp_rpontsyd"] = value
    for index, key in enumerate(keys):
        observation_date = max(walcl[key][0], tga[key][0], rrp[key][0])
        record = output.setdefault(observation_date, {})
        if _has_contiguous_month_keys(keys, index, 3):
            previous = keys[index - 3]
            walcl_delta = round(walcl[key][1] - walcl[previous][1], 6)
            tga_delta = round(tga[key][1] - tga[previous][1], 6)
            rrp_delta = round(rrp[key][1] - rrp[previous][1], 6)
            tightening_count = sum(
                (walcl_delta < 0, tga_delta > 0, rrp_delta > 0)
            )
            record.update(
                {
                    "walcl_delta_3m": walcl_delta,
                    "wtregen_delta_3m": tga_delta,
                    "rrp_delta_3m": rrp_delta,
                    "liquidity_tightening_component_count_3m": tightening_count,
                    "liquidity_2of3_3m_warning": tightening_count >= 2,
                }
            )
        output[observation_date] = record
    return output

def _asof_index(
    rows: list[tuple[date, float]], target: date, max_gap_months: int
) -> int | None:
    index = bisect_right([d for d, _ in rows], target) - 1
    if index < 0 or _month_gap(rows[index][0], target) > max_gap_months:
        return None
    return index

def _add_months(value: date, months: int) -> date:
    month_index = value.month - 1 + months
    year = value.year + month_index // 12
    month = month_index % 12 + 1
    return date(year, month, min(value.day, calendar.monthrange(year, month)[1]))

def _had_recent_blowoff_12m(
    percentiles: list[float | None], index: int
) -> bool:
    recent = [
        value
        for value in percentiles[max(0, index - 11) : index + 1]
        if value is not None
    ]
    return bool(recent and max(recent) >= 80.0)

def build_macro_rows(
    *,
    finra: dict[date, dict[str, object]],
    nfci: dict[date, dict[str, object]],
    liquidity: dict[date, dict[str, object]],
    hy_oas: dict[date, dict[str, object]],
    bdc: dict[date, dict[str, object]],
    updated_at_utc: str,
) -> list[list[object]]:
    """Form the wide descending union without filling unavailable source cells."""
    families = {
        "finra": finra,
        "nfci": nfci,
        "liquidity": liquidity,
        "hy_oas": hy_oas,
        "bdc": bdc,
    }
    all_dates: set[date] = set()
    for family in families.values():
        all_dates.update(family)
    if not all_dates:
        raise ValueError("MACRO_DATA build produced no dates")

    rows: list[list[object]] = [list(MACRO_DATA_COLUMNS)]
    for observation_date in sorted(all_dates, reverse=True):
        record: dict[str, object] = {"date": observation_date.isoformat()}
        source_status: dict[str, str] = {}
        calculation_versions: dict[str, str] = {}
        for family_name, family_rows in families.items():
            family_row = family_rows.get(observation_date)
            if family_row is None:
                source_status[family_name] = "missing"
                continue
            record.update(family_row)
            if family_name == "finra":
                available_status = str(
                    family_row.get(
                        "finra_margin_source_status",
                        "retrospective_current_vintage",
                    )
                )
            elif family_name == "bdc":
                available_status = str(family_row.get("bdc_source_status", "ok"))
            elif family_name == "hy_oas":
                available_status = "history_bridge"
            else:
                available_status = "retrospective_current_vintage"
            source_status[family_name] = available_status
            version_key, version_value = CALCULATION_VERSIONS[family_name]
            calculation_versions[version_key] = version_value
        record["source_status_json"] = json.dumps(source_status, sort_keys=True)
        record["calculation_version_json"] = json.dumps(
            calculation_versions, sort_keys=True
        )
        record["updated_at_utc"] = updated_at_utc
        rows.append([record.get(column, "") for column in MACRO_DATA_COLUMNS])
    return rows

def validate_macro_rows(rows: list[list[object]]) -> None:
    if not rows or rows[0] != list(MACRO_DATA_COLUMNS):
        raise ValueError("MACRO_DATA header mismatch")
    width = len(MACRO_DATA_COLUMNS)
    status_index = MACRO_DATA_COLUMNS.index("source_status_json")
    version_index = MACRO_DATA_COLUMNS.index("calculation_version_json")
    column_indexes = {column: index for index, column in enumerate(MACRO_DATA_COLUMNS)}
    valid_statuses = {
        "ok",
        "missing",
        "stale",
        "kept_prior",
        "retrospective_current_vintage",
        "history_bridge",
        "partial",
        "shallow_accumulation",
    }
    expected_versions = {
        version_key: version_value
        for version_key, version_value in CALCULATION_VERSIONS.values()
    }
    dates: list[str] = []
    for row in rows[1:]:
        if len(row) != width:
            raise ValueError("MACRO_DATA row width mismatch")
        raw_date = str(row[0])
        datetime.strptime(raw_date, "%Y-%m-%d")
        dates.append(raw_date)
        try:
            statuses = json.loads(str(row[status_index] or "{}"))
        except json.JSONDecodeError as exc:
            raise ValueError("invalid source status JSON") from exc
        if not isinstance(statuses, dict):
            raise ValueError("source status JSON must be an object")
        if set(statuses) != set(CALCULATION_VERSIONS):
            raise ValueError("source status JSON must contain every canonical family")
        unknown_statuses = {
            str(status) for status in statuses.values() if status not in valid_statuses
        }
        if unknown_statuses:
            raise ValueError(f"invalid source status values: {sorted(unknown_statuses)}")
        try:
            versions = json.loads(str(row[version_index] or "{}"))
        except json.JSONDecodeError as exc:
            raise ValueError("invalid calculation version JSON") from exc
        if not isinstance(versions, dict):
            raise ValueError("calculation version JSON must be an object")
        for version_key, version_value in versions.items():
            if expected_versions.get(version_key) != version_value:
                raise ValueError(
                    f"invalid calculation version: {version_key}={version_value}"
                )
        for family, family_columns in MACRO_FAMILY_COLUMNS.items():
            populated = any(
                row[column_indexes[column]] not in (None, "")
                for column in family_columns
            )
            status = statuses[family]
            version_key = MACRO_FAMILY_VERSION_KEYS[family]
            if populated:
                if status not in MACRO_POPULATED_STATUSES[family]:
                    raise ValueError(
                        f"invalid status for populated {family}: {status}"
                    )
                if versions.get(version_key) != expected_versions[version_key]:
                    raise ValueError(
                        f"populated {family} requires calculation version {version_key}"
                    )
            else:
                if status != "missing":
                    raise ValueError(
                        f"empty {family} requires missing status, got {status}"
                    )
                if version_key in versions:
                    raise ValueError(
                        f"empty {family} may not carry calculation version {version_key}"
                    )
    if len(dates) != len(set(dates)):
        raise ValueError("MACRO_DATA duplicate dates")
    if dates != sorted(dates, reverse=True):
        raise ValueError("MACRO_DATA dates must be descending")

def validate_backfill_report(report: dict[str, object]) -> None:
    """Reject latest-only or truncated full builds before a destructive batch write."""
    failures: list[str] = []

    def as_int(value: object) -> int:
        return int(value) if isinstance(value, (str, int, float)) else 0

    row_count = as_int(report.get("row_count", 0))
    if row_count < 9000:
        failures.append(f"row_count={row_count}<9000")

    expected_first_on_or_before = {
        "finra": "1997-02-01",
        "nfci": "1971-01-31",
        "liquidity": "2003-01-01",
        "hy_oas": "1997-01-01",
        "bdc": "2026-05-23",
    }
    first_dates = report.get("first_date_by_metric_family", {})
    if not isinstance(first_dates, dict):
        failures.append("first_date_by_metric_family missing")
    else:
        for family, threshold in expected_first_on_or_before.items():
            actual = str(first_dates.get(family, ""))
            if not actual or actual > threshold:
                failures.append(f"{family}.first_date={actual or 'missing'}>{threshold}")

    minimum_counts = {
        "finra_margin_debt_usd": 300,
        "nfci_leverage": 2500,
        "fed_walcl": 1000,
        "fed_tga_wtregen": 1000,
        "fed_rrp_rpontsyd": 2500,
        "hy_oas": 6000,
        "bdc_regime_c_probability": 9,
    }
    counts = report.get("non_empty_count_by_column", {})
    if not isinstance(counts, dict):
        failures.append("non_empty_count_by_column missing")
    else:
        for column, minimum in minimum_counts.items():
            actual = as_int(counts.get(column, 0))
            if actual < minimum:
                failures.append(f"{column}.count={actual}<{minimum}")
    minimum_status_counts = {
        "finra:retrospective_current_vintage": 300,
        "nfci:retrospective_current_vintage": 2500,
        "liquidity:retrospective_current_vintage": 3000,
        "hy_oas:history_bridge": 6000,
        "bdc:ok": 9,
    }
    status_counts = report.get("source_status_counts", {})
    if not isinstance(status_counts, dict):
        failures.append("source_status_counts missing")
    else:
        for status_key, minimum in minimum_status_counts.items():
            actual = as_int(status_counts.get(status_key, 0))
            if actual < minimum:
                failures.append(
                    f"source_status_counts[{status_key}]={actual}<{minimum}"
                )
    if failures:
        raise ValueError("historical source-span gate failed: " + "; ".join(failures))

def build_backfill_report(rows: list[list[object]]) -> dict[str, object]:
    validate_macro_rows(rows)
    header = [str(value) for value in rows[0]]
    records = [dict(zip(header, row)) for row in rows[1:]]
    dates = [str(record["date"]) for record in records]
    family_columns = {
        "finra": ["finra_margin_debt_usd", "finra_rollover_warning"],
        "nfci": ["nfci_leverage", "nfci_leverage_warning"],
        "liquidity": ["fed_walcl", "liquidity_2of3_3m_warning"],
        "hy_oas": ["hy_oas", "hy_oas_warning"],
        "bdc": ["bdc_as_of_date", "bdc_regime_c_probability"],
    }
    first_by_family: dict[str, str] = {}
    last_by_family: dict[str, str] = {}
    for family, columns in family_columns.items():
        available_dates = sorted(
            str(record["date"])
            for record in records
            if any(record.get(column) not in (None, "") for column in columns)
        )
        if available_dates:
            first_by_family[family] = available_dates[0]
            last_by_family[family] = available_dates[-1]

    status_counts: Counter[str] = Counter()
    calculation_versions: dict[str, str] = {}
    for record in records:
        try:
            statuses = json.loads(str(record.get("source_status_json", "{}")))
            for family, status in statuses.items():
                status_counts[f"{family}:{status}"] += 1
        except json.JSONDecodeError as exc:
            raise ValueError("invalid source_status_json") from exc
        try:
            calculation_versions.update(
                json.loads(str(record.get("calculation_version_json", "{}")))
            )
        except json.JSONDecodeError as exc:
            raise ValueError("invalid calculation_version_json") from exc

    hash_columns = [column for column in header if column != "updated_at_utc"]
    hash_payload: list[list[object]] = [list(hash_columns)]
    for record in records:
        hash_payload.append([record.get(column, "") for column in hash_columns])
    payload = json.dumps(hash_payload, ensure_ascii=False, separators=(",", ":"))
    return {
        "row_count": len(records),
        "first_date": min(dates) if dates else None,
        "last_date": max(dates) if dates else None,
        "non_empty_count_by_column": {
            column: sum(record.get(column) not in (None, "") for record in records)
            for column in header
        },
        "first_date_by_metric_family": first_by_family,
        "last_date_by_metric_family": last_by_family,
        "source_status_counts": dict(sorted(status_counts.items())),
        "calculation_version": dict(sorted(calculation_versions.items())),
        "output_sha256": hashlib.sha256(payload.encode("utf-8")).hexdigest(),
    }

def _get_client() -> gspread.Client:
    global _client
    if _client is None:
        if not settings.SPREADSHEET_ID:
            raise ValueError("Live Sheets access requires SPREADSHEET_ID and a service-account file; see README.md")
        creds = Credentials.from_service_account_file(
            settings.GOOGLE_SERVICE_ACCOUNT_FILE, scopes=SCOPES
        )
        _client = gspread.authorize(creds)
    return _client

def get_sheet(sheet_name: str) -> gspread.Worksheet:
    client = _get_client()
    spreadsheet = client.open_by_key(settings.SPREADSHEET_ID)
    return spreadsheet.worksheet(sheet_name)

def get_or_create_sheet(
    sheet_name: str,
    *,
    rows: int = 100,
    cols: int = 50,
) -> gspread.Worksheet:
    """Return an existing worksheet or create it with the requested capacity."""
    client = _get_client()
    spreadsheet = client.open_by_key(settings.SPREADSHEET_ID)
    try:
        return spreadsheet.worksheet(sheet_name)
    except gspread.exceptions.WorksheetNotFound:
        logger.info("Creating missing worksheet %s", sheet_name)
        return spreadsheet.add_worksheet(
            title=sheet_name,
            rows=max(1, rows),
            cols=max(1, cols),
        )

def get_sheet_by_id(spreadsheet_id: str, sheet_name: str) -> gspread.Worksheet:
    """Get a sheet from a specific spreadsheet ID (for windowed sheets).

    Creates the worksheet if it doesn't exist.
    """
    if not spreadsheet_id:
        raise ValueError(f"Spreadsheet ID not configured for {sheet_name}")
    client = _get_client()
    spreadsheet = client.open_by_key(spreadsheet_id)

    # Try to get existing worksheet
    try:
        return spreadsheet.worksheet(sheet_name)
    except gspread.exceptions.WorksheetNotFound:
        # Create if not found
        logger.info(f"Creating worksheet '{sheet_name}' in configured spreadsheet")
        worksheet = spreadsheet.add_worksheet(title=sheet_name, rows=100, cols=50)
        return worksheet

def read_all_values(sheet: gspread.Worksheet, *, unformatted: bool = False) -> list[list]:
    """Return all rows including header.

    Raw numeric values are opt-in so legacy merge and header callers retain
    Google Sheets display values. Date cells remain formatted strings for
    snapshot consumers that request raw numbers.
    """
    if unformatted:
        return sheet.get_all_values(
            value_render_option=ValueRenderOption.unformatted,
            date_time_render_option=DateTimeOption.formatted_string,
        )
    return sheet.get_all_values()

def upsert_rows(
    sheet: gspread.Worksheet,
    rows: list[list],
    date_col_index: int = 0,
    start_col: int | None = None,
    end_col: int | None = None,
    dry_run: bool = False,
    merge_row_transform=None,
) -> None:
    """
    Upsert rows into sheet with merge protection.

    For existing rows: only writes cells where the new value is non-empty.
    For new rows: inserts after the last newer date, preserving existing row order.

    Optional start_col/end_col are 1-based sheet columns for legacy partial
    jobs. In that mode rows are shaped as [date, value_for_start_col, ...].
    """
    if not rows:
        return

    all_values = sheet.get_all_values()
    data_rows = all_values[1:] if len(all_values) > 1 else []

    date_to_row: dict[str, int] = {}
    for i, row in enumerate(data_rows):
        if row and len(row) > date_col_index:
            date_to_row[row[date_col_index]] = i + 2  # 1-based, row 1 = header

    # Resolve start_col/end_col once so both passes can use them
    if rows and start_col is not None:
        if end_col is None:
            end_col = start_col + len(rows[0]) - 2
        if end_col < start_col:
            raise ValueError("end_col must be >= start_col")

    updates = [r for r in rows if str(r[date_col_index]) in date_to_row]
    inserts = [r for r in rows if str(r[date_col_index]) not in date_to_row]
    # Keep deterministic insertion order; each position uses the current row layout.
    inserts_asc = sorted(inserts, key=lambda r: str(r[date_col_index]))

    if dry_run:
        for new_row in rows:
            logger.info("[dry-run] upsert %s → %s", str(new_row[date_col_index]), new_row)
        return

    batch_updates: list[dict[str, object]] = []
    for new_row in updates:
        date_val = str(new_row[date_col_index])

        if start_col is not None:
            target_values = list(new_row[1:])
            expected = end_col - start_col + 1
            if len(target_values) > expected:
                raise ValueError(
                    f"partial row for {date_val} has {len(target_values)} values, "
                    f"but target range only accepts {expected}"
                )
        else:
            target_values = []

        row_num = date_to_row[date_val]
        existing = list(data_rows[row_num - 2])
        target_len = end_col if start_col is not None else len(new_row)
        while len(existing) < target_len:
            existing.append("")

        if start_col is not None:
            merged = existing[:target_len]
            if date_col_index < len(merged):
                merged[date_col_index] = date_val
            for offset, new_val in enumerate(target_values):
                target_idx = start_col - 1 + offset
                if new_val is not None and new_val != "":
                    merged[target_idx] = new_val
        else:
            merged = []
            for i, new_val in enumerate(new_row):
                if new_val is None or new_val == "":
                    merged.append(existing[i] if i < len(existing) else "")
                else:
                    merged.append(new_val)

        if merge_row_transform is not None:
            merged = merge_row_transform(existing, new_row, merged)

        col_end = gspread.utils.rowcol_to_a1(1, len(merged))[:-1]
        # Partial jobs must not rewrite preceding values/formulas via display strings.
        col_start = gspread.utils.rowcol_to_a1(1, start_col)[:-1] if start_col else "A"
        write_values = merged[start_col - 1:] if start_col else merged
        batch_updates.append(
            {"range": f"{col_start}{row_num}:{col_end}{row_num}", "values": [write_values]}
        )
        logger.debug("Prepared merged update for row %d (%s)", row_num, date_val)

    if len(batch_updates) == 1:
        update = batch_updates[0]
        sheet.update(
            update["range"],
            update["values"],
            value_input_option="USER_ENTERED",
        )
        logger.debug("Applied one merged row update")
    elif batch_updates:
        sheet.batch_update(batch_updates, value_input_option="USER_ENTERED")
        logger.debug("Applied %d merged row updates in one request", len(batch_updates))

    for new_row in inserts_asc:
        date_val = str(new_row[date_col_index])

        if start_col is not None:
            target_values = list(new_row[1:])
            insert_len = max(end_col or 0, date_col_index + 1)
            insert_row = [""] * insert_len
            insert_row[date_col_index] = date_val
            for offset, new_val in enumerate(target_values):
                target_idx = start_col - 1 + offset
                insert_row[target_idx] = "" if new_val is None else new_val
        else:
            insert_row = new_row
        # Scan rather than bisect: legacy rows may already contain an inversion.
        # After the last newer/equal date adds no new adjacent date inversion
        # and leaves the relative order of all existing rows untouched.
        insert_index = 2
        for i, row in enumerate(data_rows):
            if len(row) > date_col_index and str(row[date_col_index]) >= date_val:
                insert_index = i + 3
        sheet.insert_row(insert_row, index=insert_index)
        data_rows.insert(insert_index - 2, insert_row)
        logger.debug("Inserted new row for %s", date_val)

def batch_write(
    sheet: gspread.Worksheet,
    rows: list[list],
    dry_run: bool = False,
    column_types: dict[str, str] | None = None,
) -> None:
    """
    Overwrite the entire sheet (header + all data rows) in one batch call.

    Used for backfill where we recompute everything from scratch.
    rows[0] must be the header row.
    """
    if not rows:
        return
    if dry_run:
        logger.info("[dry-run] batch_write: %d rows (including header)", len(rows))
        return
    number_formats = {
        "date": {"type": "DATE", "pattern": "yyyy-mm-dd"},
        "datetime": {"type": "DATE_TIME", "pattern": "yyyy-mm-dd hh:mm:ss"},
        "number": {"type": "NUMBER", "pattern": "#,##0.000000"},
        "integer": {"type": "NUMBER", "pattern": "#,##0"},
        "text": {"type": "TEXT", "pattern": "@"},
        "json": {"type": "TEXT", "pattern": "@"},
    }
    if column_types is None:
        formats = [(0, 1, number_formats["date"]),
                   (1, 26, {"type": "NUMBER", "pattern": "#,##0.00"})]
    else:
        if list(column_types) != list(rows[0]):
            raise ValueError("column_types order must exactly match the batch header")
        unknown = set(column_types.values()) - (set(number_formats) | {"boolean"})
        if unknown:
            raise ValueError(f"Unsupported column types: {sorted(unknown)}")
        formats = [(i, i + 1, number_formats[kind])
                   for i, kind in enumerate(column_types.values()) if kind != "boolean"]

    # Build and validate everything before the only mutation. Explicit ExtendedValue
    # types preserve RAW semantics (including strings beginning with '=').
    row_data = []
    for row in rows:
        cells = []
        for value in row:
            if value is None or (isinstance(value, str) and value == ""):
                cells.append({})
                continue
            if isinstance(value, bool):
                entered = {"boolValue": value}
            elif isinstance(value, (int, float)):
                if not math.isfinite(value):
                    raise ValueError("batch_write requires finite numbers")
                entered = {"numberValue": value}
            elif isinstance(value, str):
                entered = {"stringValue": value}
            else:
                raise ValueError(f"Unsupported cell type: {type(value).__name__}")
            cells.append({"userEnteredValue": entered})
        row_data.append({"values": cells})

    target_rows = max(sheet.row_count, len(rows))
    target_cols = max(sheet.col_count, max(map(len, rows)),
                      26 if column_types is None else len(rows[0]))
    requests = []
    growth = {}
    if target_rows > sheet.row_count:
        growth["rowCount"] = target_rows
    if target_cols > sheet.col_count:
        growth["columnCount"] = target_cols
    if growth:
        requests.append({"updateSheetProperties": {
            "properties": {"sheetId": sheet.id, "gridProperties": growth},
            "fields": ",".join(f"gridProperties.{key}" for key in growth),
        }})
    # A range, unlike start, clears omitted old rows/columns in the same batch.
    requests.append({"updateCells": {
        "range": {"sheetId": sheet.id, "startRowIndex": 0, "startColumnIndex": 0,
                  "endRowIndex": target_rows, "endColumnIndex": target_cols},
        "rows": row_data, "fields": "userEnteredValue",
    }})
    for start, end, number_format in formats:
        requests.append({"repeatCell": {
            "range": {"sheetId": sheet.id, "startColumnIndex": start, "endColumnIndex": end},
            "cell": {"userEnteredFormat": {"numberFormat": number_format}},
            "fields": "userEnteredFormat.numberFormat",
        }})
    # Rejected batches leave values intact; timeout commit state remains unknown.
    sheet.spreadsheet.batch_update({"requests": requests})
    if growth:
        # Spreadsheet batches do not refresh Worksheet's cached grid capacity.
        # Mirror only our confirmed growth; failures leave local metadata intact.
        sheet._properties["gridProperties"].update(growth)
    logger.info("batch_write: wrote %d rows to sheet", len(rows))

def numericize(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    for col in out.columns:
        if col == "date":
            continue
        try:
            out[col] = pd.to_numeric(out[col])
        except Exception:
            pass
    return out

def normalize_macro_types(df: pd.DataFrame) -> pd.DataFrame:
    """Apply the explicit MACRO_DATA schema without coercing sparse booleans."""
    out = df.copy()

    def boolean_value(value: Any) -> bool | None:
        if value is None or value is pd.NA or value == "":
            return None
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            if pd.isna(value):
                return None
            if value in (0, 1):
                return bool(value)
        if isinstance(value, str) and value.strip().lower() in {"true", "false"}:
            return value.strip().lower() == "true"
        raise ValueError(f"invalid MACRO_DATA boolean value: {value!r}")

    for column in out.columns:
        column_type = MACRO_DATA_COLUMN_TYPES.get(column)
        if column_type == "boolean":
            out[column] = out[column].map(boolean_value).astype(object)
        elif column_type == "integer":
            numeric = pd.to_numeric(out[column], errors="coerce")
            out[column] = numeric.map(lambda value: None if pd.isna(value) else int(value)).astype(object)
        elif column_type == "number":
            out[column] = pd.to_numeric(out[column], errors="coerce")
    return out

def boolean_value(value: Any) -> bool | None:
    if value is None or value is pd.NA or value == "":
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if pd.isna(value):
            return None
        if value in (0, 1):
            return bool(value)
    if isinstance(value, str) and value.strip().lower() in {"true", "false"}:
        return value.strip().lower() == "true"
    raise ValueError(f"invalid MACRO_DATA boolean value: {value!r}")

def _with_display(thermometer: dict[str, Any]) -> dict[str, Any]:
    thermometer["display"] = {
        "renderer_version": "thermometer_v1_compact_render_v1",
        "signal_score_markdown": render_signal_score(thermometer),
    }
    return thermometer

def build_thermometer_snapshot(db: pd.DataFrame) -> dict[str, Any]:
    """Build the single versioned thermometer contract from raw DB rows.

    The score engine owns all component availability and provenance decisions;
    this consumer only selects the newest dated DB row and attaches the current
    W-SUN slot plus six retrospective weekly median slots. It never substitutes
    a fallback value.
    """
    if "date" not in db.columns:
        return _with_display(build_unavailable_thermometer_snapshot())
    frame = db.copy()
    frame["date"] = pd.to_datetime(frame["date"], errors="coerce")
    frame = frame[frame["date"].notna()].copy()
    if frame.empty:
        return _with_display(build_unavailable_thermometer_snapshot())
    frame["date"] = frame["date"].dt.date.astype(str)
    as_of = max(frame["date"])
    as_of_date = pd.Timestamp(as_of).date()
    current_monday = as_of_date - timedelta(days=as_of_date.weekday())
    first_week_day = current_monday - timedelta(days=42)
    scoring_start = first_week_day - timedelta(days=180)
    scoring_frame = frame[
        (frame["date"] >= scoring_start.isoformat()) & (frame["date"] <= as_of)
    ].copy()
    current = build_daily_thermometer(scoring_frame, as_of)
    daily_scores = {
        day: build_daily_thermometer(scoring_frame, day)
        for day in sorted(set(scoring_frame["date"]))
        if first_week_day.isoformat() <= day <= as_of
    }
    current["weekly_history"] = build_weekly_history(daily_scores, as_of)
    return _with_display(current)

def first_present(row: pd.Series, names: list[str]) -> Any:
    for name in names:
        if name in row.index and pd.notna(row[name]) and row[name] != "":
            return row[name]
    return None

def _dated_rows_newest_first(df: pd.DataFrame) -> pd.DataFrame:
    """Order a reader copy by the canonical date column, ignoring undated rows.

    Stable ties preserve the first physical row; no recency is inferred within
    a date. Callers selecting daily observations deduplicate after filtering
    missing values, so previous means a distinct earlier observation date.
    """
    frame = df.copy()
    if "date" not in frame.columns:
        frame["date"] = pd.NaT
    frame["date"] = pd.to_datetime(frame["date"], errors="coerce")
    return frame[frame["date"].notna()].sort_values(
        "date", ascending=False, kind="stable"
    )

def first_valid(df: pd.DataFrame, names: list[str]) -> tuple[Any, Any]:
    df = _dated_rows_newest_first(df)
    for name in names:
        if name in df.columns:
            s = df[["date", name]].copy()
            s = s[s[name].notna() & (s[name] != "")]
            if not s.empty:
                return s.iloc[0][name], s.iloc[0]["date"]
    return None, None

def delta(df: pd.DataFrame, names: list[str]) -> dict[str, Any]:
    df = _dated_rows_newest_first(df)
    for name in names:
        if name in df.columns:
            s = df[["date", name]].copy()
            s = s[s[name].notna() & (s[name] != "")]
            s = s.drop_duplicates("date", keep="first")
            if len(s) >= 2:
                curr = float(s.iloc[0][name])
                prev = float(s.iloc[1][name])
                d_abs = curr - prev
                d_pct = (d_abs / prev * 100) if prev else None
                return {
                    "current": curr,
                    "previous": prev,
                    "current_date": s.iloc[0]["date"],
                    "previous_date": s.iloc[1]["date"],
                    "delta_abs": d_abs,
                    "delta_pct": d_pct,
                    "column": name,
                }
            if len(s) == 1:
                return {
                    "current": float(s.iloc[0][name]),
                    "previous": None,
                    "current_date": s.iloc[0]["date"],
                    "previous_date": None,
                    "delta_abs": None,
                    "delta_pct": None,
                    "column": name,
                }
    return {"current": None, "previous": None, "delta_abs": None, "delta_pct": None, "column": None}

def rows_with_source_status(
    df: pd.DataFrame, source: str, expected_status: str | set[str]
) -> pd.DataFrame:
    """Return only rows whose per-source contract explicitly matches allowed statuses.

    Legacy rows and malformed source metadata fail closed. This prevents a
    newly corrected source contract from silently reinterpreting old values.
    """
    if "source_status_json" not in df.columns:
        return df.iloc[0:0].copy()
    allowed_statuses = {expected_status} if isinstance(expected_status, str) else expected_status

    def matches(value: Any) -> bool:
        try:
            return json.loads(value).get(source) in allowed_statuses
        except (TypeError, ValueError, json.JSONDecodeError):
            return False

    return df[df["source_status_json"].map(matches)].copy()

def matches(value: Any) -> bool:
    try:
        return json.loads(value).get(source) in allowed_statuses
    except (TypeError, ValueError, json.JSONDecodeError):
        return False

def to_jsonable(v: Any):
    if isinstance(v, pd.Timestamp):
        return v.date().isoformat()
    if isinstance(v, dict):
        return {k: to_jsonable(val) for k, val in v.items()}
    if isinstance(v, list):
        return [to_jsonable(x) for x in v]
    if v is pd.NA:
        return None
    if type(v).__module__.startswith("numpy") and hasattr(v, "item"):
        v = v.item()
    if isinstance(v, float) and pd.isna(v):
        return None
    return v

def build_macro_snapshot(macro: pd.DataFrame) -> dict[str, Any]:
    """Resolve sparse Macro families from their latest non-empty Sheet row."""
    if "date" not in macro.columns:
        return {}
    frame = macro.copy()
    frame["date"] = pd.to_datetime(frame["date"], errors="coerce")
    frame = frame[frame["date"].notna()].sort_values("date", ascending=False)
    specs = {
        "finra": {
            "value": "finra_margin_debt_usd",
            "effective_date": "finra_margin_date",
            "warning": "finra_rollover_warning",
        },
        "nfci": {
            "value": "nfci_leverage",
            "effective_date": "date",
            "warning": "nfci_leverage_warning",
        },
        "liquidity": {
            "value": "liquidity_tightening_component_count_3m",
            "effective_date": "date",
            "warning": "liquidity_2of3_3m_warning",
        },
        "hy_oas": {
            "value": "hy_oas",
            "effective_date": "date",
            "warning": "hy_oas_warning",
        },
        "bdc": {
            "value": "bdc_regime_c_probability",
            "effective_date": "bdc_as_of_date",
            "warning": None,
        },
    }
    snapshot: dict[str, Any] = {}
    for family, spec in specs.items():
        value_column = str(spec["value"])
        if value_column not in frame.columns:
            continue
        available = frame[
            frame[value_column].notna() & (frame[value_column] != "")
        ]
        if available.empty:
            continue
        row = available.iloc[0]
        effective_column = str(spec["effective_date"])
        effective_value = row.get(effective_column, row["date"])
        if pd.isna(effective_value) or effective_value == "":
            effective_value = row["date"]
        status = row.get(f"{family}_source_status")
        if not status and "source_status_json" in row.index:
            try:
                status = json.loads(row["source_status_json"] or "{}").get(family)
            except (TypeError, ValueError, json.JSONDecodeError):
                status = None
        metric_columns = {
            "finra": [
                column
                for column in MACRO_DATA_COLUMNS
                if column.startswith("finra_")
                or column in {"cpi_index", "sp500_close", "sp500_12m_high"}
            ],
            "nfci": [column for column in MACRO_DATA_COLUMNS if column.startswith("nfci_")],
            "liquidity": [
                column
                for column in MACRO_DATA_COLUMNS
                if column.startswith("fed_")
                or column.startswith("liquidity_")
                or column in {"walcl_delta_3m", "wtregen_delta_3m", "rrp_delta_3m"}
            ],
            "hy_oas": [column for column in MACRO_DATA_COLUMNS if column.startswith("hy_oas")],
            "bdc": [column for column in MACRO_DATA_COLUMNS if column.startswith("bdc_")],
        }[family]
        metrics: dict[str, Any] = {}
        for metric_column in metric_columns:
            if metric_column not in frame.columns:
                continue
            metric_rows = frame[
                frame[metric_column].notna() & (frame[metric_column] != "")
            ]
            if metric_rows.empty:
                continue
            metric_row = metric_rows.iloc[0]
            metric_effective_column = effective_column
            if family == "finra" and metric_column in {
                "sp500_close",
                "sp500_12m_high",
                "finra_sp500_near_high",
                "finra_rollover_warning",
                "finra_signal_authority",
            }:
                metric_effective_column = "date"
            metric_effective = metric_row.get(
                metric_effective_column, metric_row["date"]
            )
            if pd.isna(metric_effective) or metric_effective == "":
                metric_effective = metric_row["date"]
            metric_status = None
            metric_version = None
            try:
                metric_status = json.loads(
                    metric_row.get("source_status_json") or "{}"
                ).get(family)
            except (TypeError, ValueError, json.JSONDecodeError):
                pass
            try:
                metric_version = json.loads(
                    metric_row.get("calculation_version_json") or "{}"
                ).get(MACRO_FAMILY_VERSION_KEYS[family])
            except (TypeError, ValueError, json.JSONDecodeError):
                pass
            metrics[metric_column] = {
                "value": to_jsonable(metric_row[metric_column]),
                "sheet_date": to_jsonable(metric_row["date"]),
                "effective_date": to_jsonable(metric_effective),
                "source_status": metric_status,
                "calculation_version": metric_version,
            }
        family_snapshot: dict[str, Any] = {
            "current_value": row[value_column],
            "sheet_date": to_jsonable(row["date"]),
            "effective_date": to_jsonable(effective_value),
            "source_status": status,
            "value_column": value_column,
            "weekly_comparison": weekly_comparison(frame, [value_column], "level"),
            "metrics": metrics,
        }
        warning_column = spec.get("warning")
        if warning_column and warning_column in frame.columns:
            warning_rows = frame[
                frame[str(warning_column)].notna()
                & (frame[str(warning_column)] != "")
            ]
            if not warning_rows.empty:
                warning_row = warning_rows.iloc[0]
                family_snapshot["warning"] = warning_row[str(warning_column)]
                family_snapshot["warning_sheet_date"] = to_jsonable(warning_row["date"])
        snapshot[family] = family_snapshot
    return snapshot

def build_sector_snapshot(market: pd.DataFrame, as_of: str | None = None) -> dict:
    """Read stored closes for the last completed review week; never re-fetch prices."""
    from datetime import date, datetime, time
    from src.config.settings import SECTOR_SYMBOL_MAP
    from src.clients.market_sessions import session_close
    from zoneinfo import ZoneInfo

    now = datetime.now(ZoneInfo('America/New_York'))
    issue = date.fromisoformat(as_of) if as_of else now.date()
    cutoff = datetime.combine(issue,time.max,tzinfo=now.tzinfo) if as_of else now
    friday = issue - timedelta(days=(issue.weekday() - 4) % 7)
    def anchor(day):
        while session_close(day) is None:
            day -= timedelta(days=1)
        return day
    end = anchor(friday)
    if session_close(end)>cutoff:
        friday -= timedelta(days=7)
        end = anchor(friday)
    start = anchor(friday-timedelta(days=7))
    result = {'status':'unavailable', 'start_date':start.isoformat(), 'end_date':end.isoformat(),
              'basis':'USD price return, no dividends; SPDR sector ETF proxies', 'sectors':{}, 'benchmark':None,
              'source':'Yahoo via existing market_data_collector MARKET_DATA; sector ETF proxies, SP500 price-index benchmark'}
    required = ['SP500', *SECTOR_SYMBOL_MAP.values()]
    if market.empty or 'date' not in market or any(c not in market for c in required):
        return result
    frame = market.copy()
    frame['date'] = pd.to_datetime(frame['date'], errors='coerce')
    frame = frame[frame['date'].dt.date <= end]
    # A holiday may move an anchor back, but missing sector rows must not erase a
    # real SP500 session and silently substitute an older reporting period.
    first, last = start, end
    result.update(start_date=first.isoformat(), end_date=last.isoformat())
    anchors = []
    for day in (first, last):
        matched = frame[frame['date'].dt.date == day]
        if len(matched) != 1:
            return result
        values = pd.to_numeric(matched.iloc[0][required], errors='coerce')
        if values.isna().any() or (values <= 0).any() or not all(__import__('math').isfinite(v) for v in values):
            return result
        anchors.append(values)
    a,b = anchors
    def metric(column, url):
        return {'start_close':float(a[column]), 'end_close':float(b[column]),
                'change_pct':float((b[column]/a[column]-1)*100), 'url':url}
    result['sectors'] = {column: dict(metric(column, 'https://finance.yahoo.com/quote/'+symbol+'/'),ticker=symbol) for symbol,column in SECTOR_SYMBOL_MAP.items()}
    result['benchmark'] = metric('SP500', 'https://finance.yahoo.com/quote/%5EGSPC/')
    result['status'] = 'ready'
    return result

def anchor(day):
    while session_close(day) is None:
        day -= timedelta(days=1)
    return day

def metric(column, url):
    return {'start_close':float(a[column]), 'end_close':float(b[column]),
            'change_pct':float((b[column]/a[column]-1)*100), 'url':url}

def validate_daily_freshness(snapshot: dict, expected_date: str) -> None:
    """Require actual daily anchors, not score completeness or fetch time."""
    for path in (("db_date",), ("score", "as_of_date"),
                 ("indicators", "btc", "current_date"),
                 ("market_data", "BTC", "current_date")):
        value = snapshot
        for key in path:
            value = value.get(key) if isinstance(value, dict) else None
        # Exact ISO equality also rejects missing, malformed and future dates.
        if not isinstance(value, str) or value != expected_date:
            raise ValueError(f"daily freshness: {'.'.join(path)} must be {expected_date}")

def main(argv=None):
    import argparse
    parser = argparse.ArgumentParser(description='Read-only Sheet-backed market snapshot')
    parser.add_argument('--sectors-only', action='store_true')
    parser.add_argument('--as-of', help='Sector review issue date YYYY-MM-DD')
    parser.add_argument('--require-current-daily', action='store_true',
                        help='Require closed Europe/Berlin yesterday for DB, score and BTC observations')
    args = parser.parse_args(argv or [])
    if args.require_current_daily and (args.sectors_only or args.as_of):
        parser.error('--require-current-daily cannot be combined with sector/historical options')
    if args.as_of and not args.sectors_only:
        parser.error('--as-of applies only with --sectors-only; existing BTC snapshot is not a historical replay')
    if args.sectors_only:
        print(json.dumps(build_sector_snapshot(numericize(sheet_to_df('MARKET_DATA')), args.as_of), ensure_ascii=False, indent=2))
        return
    db = numericize(sheet_to_df("DB"))
    market = numericize(sheet_to_df("MARKET_DATA"))
    macro = (
        normalize_macro_types(sheet_to_df("MACRO_DATA"))
        if MACRO_DATA_CONSUMER_ENABLED
        else pd.DataFrame()
    )

    dated_db = _dated_rows_newest_first(db)
    if dated_db.empty:
        raise ValueError("DB contains no valid dated rows")
    today_db = dated_db.iloc[0]
    dated_market = _dated_rows_newest_first(market)
    liq_db = rows_with_source_status(db, "liq", {"ok_usd_v2", "kept_prior"})

    source_status = first_present(today_db, DB_FALLBACKS["source_status"])
    try:
        source_status = json.loads(source_status) if source_status else {}
    except Exception:
        source_status = {"raw": source_status}

    snapshot = {
        "db_date": today_db["date"],
        "market_date": dated_market.iloc[0]["date"] if not dated_market.empty else None,
        "score": build_thermometer_snapshot(db),
        "indicators": {
            "btc": weekly_metric(db, DB_FALLBACKS["btc"], "level"),
            "mstr": weekly_metric(db, DB_FALLBACKS["mstr"], "level"),
            "fear_greed": weekly_metric(db, DB_FALLBACKS["fear_greed"], "level"),
            "mvrv": weekly_metric(db, DB_FALLBACKS["mvrv"], "level"),
            "btc_200w_ma_usd": weekly_metric(db, DB_FALLBACKS["ma_200w"], "level"),
            "btc_200w_ma_ratio_pct": weekly_metric(db, DB_FALLBACKS["ma_ratio_pct"], "level"),
            "cb_premium_usd": weekly_metric(db, DB_FALLBACKS["cb_premium"], "level"),
            "perp_oi_usd": weekly_metric(db, DB_FALLBACKS["oi"], "level"),
            **({
                "liq_daily_total_usd": weekly_metric(liq_db, DB_FALLBACKS["liq_total"], "flow"),
                "liq_7d_long_pct": weekly_metric(liq_db, DB_FALLBACKS["liq_long_pct"], "pre_windowed"),
            } if not liq_db.empty else {}),
            "mstr_btc_ratio": weekly_metric(db, DB_FALLBACKS["mstr_btc_ratio"], "level"),
            "btc_etf_total_flow_usd_m": weekly_metric(db, DB_FALLBACKS["etf_flows"], "flow"),
            "flex_signal": {"current": first_present(today_db, DB_FALLBACKS["flex_signal"]), "column": "flex_signal", "weekly_comparison": {"schema_version": 2, "metric_class": "display_only", "reference_available": False}},
        },
        "market_data": {
            col: weekly_metric(market, [col], "level") for col in [
                "BTC", "MSTR", "STRK", "STRF", "STRD", "STRC", "SP500", "NASDAQ100",
                "GOLD", "DXY", "Smartgrid_ETF", "WNUC_Euro", "5MVW_Euro", "PTC", "MSCI_World_Core"
            ] if col in market.columns
        },
        "macro": build_macro_snapshot(macro),
        "sectors": build_sector_snapshot(market),
        "source_status": source_status,
    }
    snapshot = to_jsonable(snapshot)
    if args.require_current_daily:
        expected_date = (datetime.now(ZoneInfo('Europe/Berlin')).date() - timedelta(days=1)).isoformat()
        try:
            validate_daily_freshness(snapshot, expected_date)
        except ValueError as exc:
            parser.error(str(exc))
    print(json.dumps(snapshot, ensure_ascii=False, indent=2))

def _freeze(value: Any) -> Any:
    if isinstance(value, dict):
        return MappingProxyType({key: _freeze(item) for key, item in value.items()})
    if isinstance(value, list):
        return tuple(_freeze(item) for item in value)
    return value

def component_contracts_for_snapshot() -> Dict[str, Any]:
    """Return a detached, JSON-serializable v1 contract projection."""
    return json.loads(json.dumps(_COMPONENT_CONTRACTS_V1, default=dict))

def validate_component_contracts(value: Any) -> bool:
    """Accept only the immutable v1 contract projection emitted by this module."""
    return value == component_contracts_for_snapshot()

def _number(value: Any) -> Optional[float]:
    if value is None or isinstance(value, bool):
        return None
    try:
        if pd.isna(value):
            return None
    except TypeError:
        pass
    try:
        result = float(value)
    except (TypeError, ValueError):
        return None
    return result if math.isfinite(result) else None

def _status(value: Any) -> Dict[str, Any]:
    if isinstance(value, dict):
        return value
    if not isinstance(value, str) or not value:
        return {}
    try:
        parsed = json.loads(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    return parsed if isinstance(parsed, dict) else {}

def _as_iso_date(value: Any) -> Optional[str]:
    if isinstance(value, date):
        return value.isoformat()
    try:
        parsed = pd.Timestamp(value)
    except (TypeError, ValueError):
        return None
    return parsed.date().isoformat() if not pd.isna(parsed) else None

def score_mvrv(value: Any) -> Optional[int]:
    raw = _number(value)
    if raw is None or raw <= 0:
        return None
    if raw < 1.3:
        return 2
    if raw < 1.5:
        return 1
    if raw <= 2.5:
        return 0
    return -2

def score_fear_greed(value: Any) -> Optional[int]:
    raw = _number(value)
    if raw is None or not 0 <= raw <= 100:
        return None
    if raw < 15:
        return 2
    if raw < 25:
        return 1
    if raw <= 75:
        return 0
    return -2

def percentile_points(current: Any, reference: Iterable[Any]) -> Optional[int]:
    current_value = _number(current)
    values = [_number(value) for value in reference]
    if current_value is None or len(values) != 180 or any(value is None for value in values):
        return None
    percentile = sum(value <= current_value for value in values if value is not None) / 180
    if percentile <= 0.20:
        return 2
    if percentile <= 0.40:
        return 1
    if percentile <= 0.60:
        return 0
    if percentile <= 0.80:
        return -1
    return -2

def bucket_for_score(score: int) -> str:
    if not isinstance(score, int) or score < -8 or score > 8:
        raise ValueError("score must be an integer in [-8, 8]")
    if score >= 6:
        return "A"
    if score >= 3:
        return "B"
    if score >= 0:
        return "C"
    if score >= -3:
        return "D"
    return "E"

def _component(component_id: str, raw: Any, points: Optional[int], reason_code: Optional[str] = None) -> Dict[str, Any]:
    if points is None:
        return {
            "id": component_id,
            "contract_version": SCORE_SCHEMA_VERSION,
            "status": "unavailable",
            "raw": None if _number(raw) is None else _number(raw),
            "points": None,
            "reason_code": reason_code or "missing_raw_value",
        }
    return {
        "id": component_id,
        "contract_version": SCORE_SCHEMA_VERSION,
        "status": "available",
        "raw": _number(raw),
        "points": points,
        "reason_code": None,
    }

def _frame_by_date(records: Any) -> Dict[str, Mapping[str, Any]]:
    frame = records.copy() if isinstance(records, pd.DataFrame) else pd.DataFrame(records)
    if "date" not in frame.columns:
        return {}
    result: Dict[str, Mapping[str, Any]] = {}
    for _, row in frame.iterrows():
        day = _as_iso_date(row.get("date"))
        if day is not None and day not in result:
            result[day] = row.to_dict()
    return result

def _calendar_window(rows: Mapping[str, Mapping[str, Any]], as_of: date) -> Tuple[Optional[List[Mapping[str, Any]]], Optional[str]]:
    window: List[Mapping[str, Any]] = []
    for offset in range(180, 0, -1):
        expected = (as_of - timedelta(days=offset)).isoformat()
        row = rows.get(expected)
        if row is None:
            return None, "missing_calendar_day_in_180d_window"
        window.append(row)
    return window, None

def _cb_component(rows: Mapping[str, Mapping[str, Any]], as_of: date) -> Dict[str, Any]:
    current = rows.get(as_of.isoformat())
    if current is None:
        return _component("cb_premium", None, None, "missing_raw_value")
    current_status = _status(current.get("source_status_json"))
    if current_status.get("coinbase") != "ok" or current_status.get("binance") != "ok":
        return _component("cb_premium", current.get("cb_premium_pct"), None, "source_status_not_ok")
    if _number(current.get("btc_binance_close")) is None or _number(current.get("btc_binance_close")) <= 0 or _number(current.get("btc_coinbase_close")) is None:
        return _component("cb_premium", current.get("cb_premium_pct"), None, "invalid_raw_value")
    window, error = _calendar_window(rows, as_of)
    if error:
        return _component("cb_premium", current.get("cb_premium_pct"), None, error)
    reference: List[Any] = []
    for row in window or []:
        status = _status(row.get("source_status_json"))
        if status.get("coinbase") != "ok" or status.get("binance") != "ok":
            return _component("cb_premium", current.get("cb_premium_pct"), None, "component_identity_mismatch")
        if _number(row.get("btc_binance_close")) is None or _number(row.get("btc_binance_close")) <= 0 or _number(row.get("btc_coinbase_close")) is None:
            return _component("cb_premium", current.get("cb_premium_pct"), None, "invalid_raw_value")
        reference.append(row.get("cb_premium_pct"))
    points = percentile_points(current.get("cb_premium_pct"), reference)
    return _component("cb_premium", current.get("cb_premium_pct"), points, "insufficient_180d_complete_window")

def _valid_oi_provenance(provenance: Any) -> Tuple[bool, str]:
    if not isinstance(provenance, dict):
        return False, "basket_provenance_missing"
    if provenance.get("basket_id") != OI_BASKET_ID:
        return False, "basket_identity_mismatch"
    if provenance.get("provider") != "coinalyze" or provenance.get("endpoint") != "/v1/open-interest-history" or provenance.get("interval") != "daily" or provenance.get("field") != "c" or provenance.get("convert_to_usd") is not True:
        return False, "basket_identity_mismatch"
    expected = provenance.get("expected_symbols")
    observed = provenance.get("observed_symbols")
    if expected != list(OI_SYMBOLS) or not isinstance(observed, list) or len(set(observed)) != len(observed) or set(observed) != set(OI_SYMBOLS):
        return False, "unexpected_or_missing_oi_symbols"
    if provenance.get("expected_symbol_count") != 9 or provenance.get("observed_symbol_count") != 9:
        return False, "unexpected_or_missing_oi_symbols"
    if _number(provenance.get("coverage_pct")) != 100.0:
        return False, "oi_coverage_not_100"
    return True, ""

def _oi_component(rows: Mapping[str, Mapping[str, Any]], as_of: date) -> Dict[str, Any]:
    current = rows.get(as_of.isoformat())
    if current is None:
        return _component("oi", None, None, "missing_raw_value")
    current_status = _status(current.get("source_status_json"))
    if current_status.get("oi") != "ok":
        return _component("oi", current.get("perp_oi_usd"), None, "source_status_not_ok")
    valid, reason = _valid_oi_provenance(current_status.get("oi_basket_v1"))
    if not valid:
        return _component("oi", current.get("perp_oi_usd"), None, reason)
    window, error = _calendar_window(rows, as_of)
    if error:
        return _component("oi", current.get("perp_oi_usd"), None, error)
    reference: List[Any] = []
    for row in window or []:
        status = _status(row.get("source_status_json"))
        if status.get("oi") != "ok":
            return _component("oi", current.get("perp_oi_usd"), None, "source_status_not_ok")
        valid, reason = _valid_oi_provenance(status.get("oi_basket_v1"))
        if not valid:
            return _component("oi", current.get("perp_oi_usd"), None, reason)
        reference.append(row.get("perp_oi_usd"))
    points = percentile_points(current.get("perp_oi_usd"), reference)
    return _component("oi", current.get("perp_oi_usd"), points, "insufficient_180d_complete_window")

def _threshold_component(component_id: str, row: Optional[Mapping[str, Any]], source_key: str, raw_key: str, scorer) -> Dict[str, Any]:
    if row is None:
        return _component(component_id, None, None, "missing_raw_value")
    status = _status(row.get("source_status_json"))
    if status.get(source_key) != "ok":
        return _component(component_id, row.get(raw_key), None, "source_status_not_ok")
    points = scorer(row.get(raw_key))
    reason = "invalid_raw_value" if _number(row.get(raw_key)) is not None and points is None else "missing_raw_value"
    return _component(component_id, row.get(raw_key), points, reason)

def build_daily_thermometer(records: Any, as_of_date: str) -> Dict[str, Any]:
    """Build one v1 daily object without I/O or fallback column selection."""
    try:
        as_of = date.fromisoformat(as_of_date)
    except (TypeError, ValueError):
        raise ValueError("as_of_date must be YYYY-MM-DD")
    rows = _frame_by_date(records)
    components = {
        "cb_premium": _cb_component(rows, as_of),
        "oi": _oi_component(rows, as_of),
        "mvrv": _threshold_component("mvrv", rows.get(as_of.isoformat()), "mvrv", "mvrv", score_mvrv),
        "fear_greed": _threshold_component("fear_greed", rows.get(as_of.isoformat()), "fear_greed", "fear_greed", score_fear_greed),
    }
    if tuple(components) != ACTIVE_COMPONENT_IDS:
        raise RuntimeError("active v1 component implementation drift")
    available = {name: value["points"] for name, value in components.items() if value["status"] == "available"}
    missing = [
        {"id": value["id"], "status": "unavailable", "reason_code": value["reason_code"]}
        for value in components.values() if value["status"] != "available"
    ]
    base: Dict[str, Any] = {
        "score_schema_version": SCORE_SCHEMA_VERSION,
        "as_of_date": as_of.isoformat(),
        "components": components,
        "component_contracts": component_contracts_for_snapshot(),
        "funding_diagnostic": dict(FUNDING_DIAGNOSTIC),
        "weekly_history": [],
    }
    if len(available) == 4:
        score = sum(available.values())
        base.update({"status": "complete", "score": {"value": score, "min": -8, "max": 8}, "bucket": bucket_for_score(score)})
    elif available:
        base.update({"status": "partial", "score": None, "bucket": None, "available_component_points": available, "missing_components": missing})
    else:
        base.update({"status": "unavailable", "score": None, "bucket": None, "available_component_points": {}, "missing_components": missing})
    return base

def build_unavailable_thermometer_snapshot(as_of: Optional[date] = None) -> Dict[str, Any]:
    """Build the complete v1 unavailable shape when no usable DB date exists."""
    components = {
        component_id: _component(component_id, None, None, "missing_db_date")
        for component_id in ACTIVE_COMPONENT_IDS
    }
    missing = [
        {"id": value["id"], "status": "unavailable", "reason_code": value["reason_code"]}
        for value in components.values()
    ]
    history_as_of = as_of or date.today()
    current_monday = history_as_of - timedelta(days=history_as_of.weekday())
    first_day = current_monday - timedelta(days=35)
    unavailable_days = {
        (first_day + timedelta(days=offset)).isoformat(): {
            "score_schema_version": SCORE_SCHEMA_VERSION,
            "status": "unavailable",
            "missing_components": missing,
        }
        for offset in range(42)
    }
    return {
        "score_schema_version": SCORE_SCHEMA_VERSION,
        "status": "unavailable",
        "reason_code": "missing_db_date",
        "components": components,
        "component_contracts": component_contracts_for_snapshot(),
        "funding_diagnostic": dict(FUNDING_DIAGNOSTIC),
        "score": None,
        "bucket": None,
        "available_component_points": {},
        "missing_components": missing,
        "weekly_history": build_weekly_history(unavailable_days, history_as_of.isoformat()),
    }

def build_weekly_history(daily_scores: Mapping[str, Mapping[str, Any]], as_of_date: str) -> List[Dict[str, Any]]:
    """Return current W-SUN slot plus six historical slots; a median requires seven complete v1 days."""
    as_of = date.fromisoformat(as_of_date)
    current_monday = as_of - timedelta(days=as_of.weekday())
    slots: List[Dict[str, Any]] = []
    for week_offset in range(7):
        week_start = current_monday - timedelta(days=7 * week_offset)
        dates = [week_start + timedelta(days=offset) for offset in range(7)]
        complete_values: List[int] = []
        missing_dates: List[str] = []
        missing_reasons: List[Dict[str, Any]] = []
        for day in dates:
            day_key = day.isoformat()
            daily = daily_scores.get(day_key)
            if daily and daily.get("score_schema_version") == SCORE_SCHEMA_VERSION and daily.get("status") == "complete" and isinstance(daily.get("score"), dict) and isinstance(daily["score"].get("value"), int):
                complete_values.append(daily["score"]["value"])
                continue
            missing_dates.append(day_key)
            for component in (daily or {}).get("missing_components", []):
                if isinstance(component, dict):
                    missing_reasons.append({"date": day_key, "component": component.get("id"), "reason_code": component.get("reason_code")})
        common = {
            "week_start": week_start.isoformat(),
            "week_end": dates[-1].isoformat(),
            "label": "median_of_complete_daily_scores",
            "complete_day_count": len(complete_values),
            "missing_dates": missing_dates,
            "missing_reasons": missing_reasons,
        }
        if len(complete_values) == 7:
            slots.append({**common, "status": "complete", "median": float(pd.Series(complete_values).median())})
        elif len(complete_values) == 6:
            slots.append({**common, "status": "partial", "median": float(pd.Series(complete_values).median())})
        else:
            slots.append({**common, "status": "unavailable", "median": None})
    return slots

def _score(value: Any) -> str:
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        return "—"
    numeric = float(value)
    return f"{int(numeric):+d}" if numeric.is_integer() else f"{numeric:+.1f}"

def _bucket_for_weekly_median(value: float) -> str:
    """Classify an exact weekly median; daily score validation remains integer-only."""
    if value < -8 or value > 8:
        raise ValueError("weekly median must be in [-8, 8]")
    if value >= 6:
        return "A"
    if value >= 3:
        return "B"
    if value >= 0:
        return "C"
    if value >= -3:
        return "D"
    return "E"

def render_signal_score(thermometer: Mapping[str, Any]) -> str:
    """Render the canonical compact v1 table; never mixes legacy values."""
    if not isinstance(thermometer, Mapping) or thermometer.get("score_schema_version") != SCHEMA_VERSION:
        raise ValueError("display requires composite_thermometer_v1")
    status = thermometer.get("status")
    if status not in {"complete", "partial", "unavailable"}:
        raise ValueError("display requires complete, partial, or unavailable status")
    if status == "complete" and isinstance(thermometer.get("score"), Mapping):
        headline = f"**Thermometer v1:** {_score(thermometer['score'].get('value'))} — Bucket {thermometer.get('bucket')}."
    elif status == "partial":
        headline = "**Thermometer v1:** teilweise nicht verfügbar — Datenstand prüfen."
    else:
        headline = "**Thermometer v1:** nicht verfügbar — Datenstand prüfen."
    return "\n".join([
        "## Signal-Score", "", headline, "", "### 6-Wochen-Verlauf (Wochenmediane)",
        "| Kalenderwoche | Score | Bucket | Δ1W |", "|---|---:|:---:|---:|",
        *_weekly_rows(thermometer.get("weekly_history")), "",
        "*Median bei 6 oder 7 vollständigen Tageswerten. Keine Legacy-Vergleiche.*",
    ])

def _project_path(value: str, default: str) -> str:
    """Resolve relative project paths to absolute paths.

    launchd can be picky about working directories. Keep .env ergonomic while
    ensuring runtime paths are deterministic.
    """
    raw = value or default
    path = Path(raw).expanduser()
    if not path.is_absolute():
        path = PROJECT_ROOT / path
    return str(path)

def _macro_column_type(column: str) -> str:
    if column in _MACRO_DATE_COLUMNS:
        return "date"
    if column == "updated_at_utc":
        return "datetime"
    if column in _MACRO_BOOLEAN_COLUMNS:
        return "boolean"
    if column in _MACRO_INTEGER_COLUMNS:
        return "integer"
    if column in _MACRO_TEXT_COLUMNS:
        return "text"
    if column in _MACRO_JSON_COLUMNS:
        return "json"
    return "number"

def _parse_status(value: Any, day: str) -> dict[str, Any]:
    if value in (None, ""):
        return {}
    try:
        parsed = json.loads(value) if isinstance(value, str) else value
    except json.JSONDecodeError as exc:
        raise ValueError(f"{day}: source_status_json is invalid") from exc
    if not isinstance(parsed, dict):
        raise ValueError(f"{day}: source_status_json is invalid")
    return dict(parsed)

def _fetch_complete(start: date, end: date) -> dict[str, dict[str, Any]]:
    expected = _dates(start, end)
    # Coinalyze's daily-history endpoint returns the requested range in one
    # response.  Splitting it would multiply API credits by the nine symbols.
    received = fetch_open_interest_provenance(start.isoformat(), end.isoformat())
    missing = sorted(set(expected) - set(received))
    if missing:
        raise ValueError(f"Deribit OI is incomplete; first missing dates: {missing[:3]}")
    for day in expected:
        item = received[day]
        if item.get("basket_id") != OI_BASKET_ID or item.get("coverage_pct") != 100.0:
            raise ValueError(f"{day}: Deribit OI provenance is incomplete")
    return received

def _read_sheet() -> tuple[list[str], list[list[Any]], dict[str, int]]:
    values = read_all_values(get_sheet(DB_SHEET), unformatted=True)
    if not values:
        raise ValueError("DB sheet is empty")
    header = [str(value) for value in values[0]]
    missing = set(("date", *TARGET_COLUMNS)) - set(header)
    if missing or len(set(header)) != len(header):
        raise ValueError(f"DB schema invalid; missing={sorted(missing)}")
    return header, values[1:], {name: header.index(name) for name in header}

def _plan(header: list[str], rows: list[list[Any]], indexes: dict[str, int], provenance: dict[str, dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    date_index = indexes["date"]
    by_date: dict[str, tuple[int, list[Any]]] = {}
    for row_number, row in enumerate(rows, start=2):
        if len(row) <= date_index:
            continue
        day = str(row[date_index])
        if day in by_date:
            raise ValueError(f"duplicate DB date: {day}")
        by_date[day] = (row_number, list(row))
    target_dates = sorted(provenance)
    missing = [day for day in target_dates if day not in by_date]
    if missing:
        raise ValueError(f"DB missing Deribit target dates: {missing[:3]}")

    frame_rows: list[dict[str, Any]] = []
    for row_number, row in enumerate(rows, start=2):
        record = {name: (row[i] if i < len(row) else None) for i, name in enumerate(header)}
        day = str(record.get("date", ""))
        if day in provenance:
            item = provenance[day]
            status = _parse_status(record.get("source_status_json"), day)
            status["oi"] = "ok"
            status["oi_basket_v1"] = {key: value for key, value in item.items() if key != "value"}
            record["perp_oi_usd"] = item["value"]
            record["oi_coverage_pct"] = item["coverage_pct"]
            record["source_status_json"] = json.dumps(status, sort_keys=True, separators=(",", ":"))
        frame_rows.append(record)
    frame = pd.DataFrame(frame_rows)
    frame["date"] = pd.to_datetime(frame["date"], errors="raise")
    frame = numericize(frame).sort_values("date").reset_index(drop=True)
    recomputed = compute_all(frame).set_index(frame["date"].dt.date.astype(str))

    updates: list[dict[str, Any]] = []
    backup: list[dict[str, Any]] = []
    for day in target_dates:
        row_number, original = by_date[day]
        changed: dict[str, Any] = {}
        before: dict[str, Any] = {}
        for name in TARGET_COLUMNS:
            column = indexes[name]
            old = original[column] if column < len(original) else ""
            value = recomputed.loc[day, name]
            if pd.isna(value):
                value = ""
            elif hasattr(value, "item"):
                value = value.item()
            changed[name] = value
            before[name] = old
        updates.append({"date": day, "row": row_number, "values": changed})
        backup.append({"date": day, "row": row_number, "values": before})
    return updates, backup

def _backup(backup: list[dict[str, Any]], directory: Path, series_start: date) -> Path:
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / f"oi_deribit_v2_backup_{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}.json"
    payload = {"contract": "oi_deribit_v2_backfill", "series_start": series_start.isoformat(), "columns": list(TARGET_COLUMNS), "original": backup}
    fd, temp = tempfile.mkstemp(dir=directory, prefix=".oi-backup.")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, sort_keys=True); handle.write("\n"); handle.flush(); os.fsync(handle.fileno())
        os.replace(temp, path)
    finally:
        if os.path.exists(temp): os.unlink(temp)
    return path

def _scope_days() -> list[str]:
    start = date.fromisoformat(VERIFIED_START_DATE)
    end = date.fromisoformat(VERIFIED_END_DATE)
    days = [
        (start + timedelta(days=offset)).isoformat()
        for offset in range((end - start).days + 1)
    ]
    if len(days) != VERIFIED_DAY_COUNT:
        raise RuntimeError("verified OI scope day count no longer equals 640")
    return days

def _as_number(value: Any, label: str) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} is not numeric") from exc
    if not math.isfinite(number):
        raise ValueError(f"{label} is not finite")
    return number

def _parse_status(value: Any, day: str) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    if value in (None, ""):
        return {}
    try:
        status = json.loads(value)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError(f"{day}: source_status_json is not an object") from exc
    if not isinstance(status, dict):
        raise ValueError(f"{day}: source_status_json is not an object")
    return status

def plan_verified_oi_provenance_updates(
    db_rows: Iterable[Mapping[str, Any]], refetched: Mapping[str, Mapping[str, Any]]
) -> dict[str, str]:
    """Validate the complete scope before returning source-status-only updates.

    The inputs are never mutated.  Any missing DB row, duplicate, partial
    basket, unexpected date, or value mismatch aborts before a caller receives
    even a partial plan.
    """
    scope_days = _scope_days()
    scope = set(scope_days)
    rows_by_day: dict[str, Mapping[str, Any]] = {}
    for row in db_rows:
        day = row.get("date")
        if day in scope:
            if day in rows_by_day:
                raise ValueError(f"{day}: duplicate DB row in verified scope")
            rows_by_day[day] = row

    missing_rows = sorted(scope - set(rows_by_day))
    if missing_rows:
        raise ValueError(f"missing DB rows in verified scope: {missing_rows[:3]}")
    if set(refetched) != scope:
        missing = sorted(scope - set(refetched))
        extra = sorted(set(refetched) - scope)
        raise ValueError(f"refetch dates must equal the 640-day scope; missing={missing[:3]}, extra={extra[:3]}")

    plan: dict[str, str] = {}
    for day in scope_days:
        row = rows_by_day[day]
        provenance = refetched[day]
        persisted_oi = _as_number(row.get("perp_oi_usd"), f"{day}: DB perp_oi_usd")
        refetched_oi = _as_number(provenance.get("value"), f"{day}: refetched OI")
        if abs(persisted_oi - refetched_oi) > 0.01:
            raise ValueError(f"{day}: OI mismatch exceeds 0.01")
        status = _parse_status(row.get("source_status_json"), day)
        status["oi_basket_v1"] = _validated_provenance(day, provenance)
        plan[day] = json.dumps(status, sort_keys=True, separators=(",", ":"))

    if len(plan) != VERIFIED_DAY_COUNT:
        raise RuntimeError("refusing incomplete OI provenance plan")
    return plan

def _fetch_in_safe_chunks() -> dict[str, dict[str, Any]]:
    days = _scope_days()
    all_refetched: dict[str, dict[str, Any]] = {}
    for start_index in range(0, len(days), MAX_CHUNK_DAYS):
        chunk = days[start_index:start_index + MAX_CHUNK_DAYS]
        received = fetch_open_interest_provenance(chunk[0], chunk[-1])
        overlap = set(all_refetched).intersection(received)
        if overlap:
            raise ValueError(f"duplicate refetched days across chunks: {sorted(overlap)[:3]}")
        all_refetched.update(received)
        if start_index + MAX_CHUNK_DAYS < len(days):
            time.sleep(CHUNK_PAUSE_SECONDS)
    return all_refetched

def _read_db_rows() -> list[dict[str, Any]]:
    values = read_all_values(get_sheet(DB_SHEET_NAME), unformatted=True)
    if not values:
        raise ValueError("DB sheet is empty")
    header = values[0]
    if len(set(header)) != len(header) or not _REQUIRED_DB_COLUMNS.issubset(header):
        raise ValueError(f"DB sheet lacks required columns: {_REQUIRED_DB_COLUMNS}")
    return [dict(zip(header, row)) for row in values[1:] if row]

def _column_letter(column_number: int) -> str:
    """Return the A1 column name for a positive one-based column number."""
    if column_number < 1:
        raise ValueError("sheet column number must be positive")
    result = ""
    while column_number:
        column_number, remainder = divmod(column_number - 1, 26)
        result = chr(ord("A") + remainder) + result
    return result

def _apply_targets(values: list[list[Any]], updates: Mapping[str, str]) -> list[dict[str, Any]]:
    """Bind a complete validated plan to exactly the existing status cells."""
    if not values:
        raise ValueError("DB sheet is empty")
    header = values[0]
    if len(set(header)) != len(header) or not _REQUIRED_DB_COLUMNS.issubset(header):
        raise ValueError(f"DB sheet lacks required columns: {_REQUIRED_DB_COLUMNS}")
    if set(updates) != set(_scope_days()) or len(updates) != VERIFIED_DAY_COUNT:
        raise RuntimeError("refusing apply without the complete verified OI provenance plan")

    date_index = header.index("date")
    status_index = header.index("source_status_json")
    scope = set(_scope_days())
    by_day: dict[str, tuple[int, list[Any]]] = {}
    for row_number, row in enumerate(values[1:], start=2):
        if len(row) <= date_index:
            continue
        day = str(row[date_index])
        if day not in scope:
            continue
        if day in by_day:
            raise ValueError(f"{day}: duplicate DB row in verified scope")
        by_day[day] = (row_number, row)

    missing = sorted(scope - set(by_day))
    if missing:
        raise ValueError(f"missing DB rows in verified scope: {missing[:3]}")

    column = _column_letter(status_index + 1)
    targets: list[dict[str, Any]] = []
    for day in _scope_days():
        row_number, row = by_day[day]
        original = row[status_index] if len(row) > status_index else ""
        targets.append({
            "day": day,
            "range": f"{column}{row_number}",
            "original": original,
            "target": updates[day],
        })
    if len(targets) != VERIFIED_DAY_COUNT:
        raise RuntimeError("refusing incomplete OI provenance apply target set")
    return targets

def _verify_readback(sheet: Any, targets: list[dict[str, Any]], backup_path: Path) -> int:
    readback = sheet.batch_get([target["range"] for target in targets])
    if len(readback) != len(targets):
        raise RuntimeError(f"read-back mismatch; backup retained at {backup_path}")
    for target, returned in zip(targets, readback):
        # gspread returns ValueRange (a list subclass); lightweight test or API
        # adapters may return the underlying ValueRange JSON mapping instead.
        returned_values = returned.get("values", []) if isinstance(returned, Mapping) else returned
        actual = (
            returned_values[0][0]
            if isinstance(returned_values, list)
            and len(returned_values) == 1
            and isinstance(returned_values[0], list)
            and len(returned_values[0]) == 1
            else None
        )
        if actual != target["target"]:
            raise RuntimeError(
                f"read-back mismatch for {target['range']}; backup retained at {backup_path}"
            )
    return len(targets)

def to_unix_ms(date_str: str) -> int:
    """Convert YYYY-MM-DD to Unix timestamp in milliseconds (UTC midnight)."""
    d = date.fromisoformat(date_str)
    from datetime import datetime, timezone
    dt = datetime(d.year, d.month, d.day, tzinfo=timezone.utc)
    return int(dt.timestamp() * 1000)

def to_unix_s(date_str: str) -> int:
    """Convert YYYY-MM-DD to Unix timestamp in seconds (UTC midnight)."""
    return to_unix_ms(date_str) // 1000
